css:
/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-plan {
  width: 100%;
  height: var(--dhr-plan-h, 680px);
  container-type: inline-size;
  container-name: dhr-plan;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-plan-bg);
  color: var(--dhr-plan-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-plan-accent);
  scrollbar-color: var(--dhr-plan-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-plan-focus, var(--dhr-plan-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@property --dhr-plan-n { syntax: "<integer>"; inherits: false; initial-value: 0; }
@keyframes dhr-plan-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhr-plan-rise { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-plan-row { from { opacity: 0.15; translate: 0 10px; } }

.dhr-plan {
  /* re-theme: paper, ink, accent and the plan line */
  --dhr-plan-bg: oklch(0.972 0.006 92);
  --dhr-plan-ink: oklch(0.26 0.014 75);
  --dhr-plan-accent: oklch(0.52 0.11 156);
  --dhr-plan-plan: oklch(0.3 0.02 70);
  --dhr-plan-neg: oklch(0.56 0.15 32);
  --dhr-plan-eng: oklch(0.56 0.1 162);
  --dhr-plan-pd: oklch(0.76 0.12 82);
  --dhr-plan-sal: oklch(0.65 0.12 42);
  --dhr-plan-cs: oklch(0.6 0.07 238);
  --dhr-plan-ops: oklch(0.72 0.09 125);
  --dhr-plan-ga: oklch(0.58 0.07 332);

  --dhr-plan-card: color-mix(in oklch, var(--dhr-plan-bg), white 72%);
  --dhr-plan-sunk: color-mix(in oklch, var(--dhr-plan-bg), var(--dhr-plan-ink) 4%);
  --dhr-plan-line: color-mix(in oklch, var(--dhr-plan-ink) 10%, transparent);
  --dhr-plan-line2: color-mix(in oklch, var(--dhr-plan-ink) 20%, transparent);
  --dhr-plan-muted: color-mix(in oklch, var(--dhr-plan-ink) 62%, var(--dhr-plan-bg));
  --dhr-plan-faint: color-mix(in oklch, var(--dhr-plan-ink) 40%, var(--dhr-plan-bg));
  --dhr-plan-pos: var(--dhr-plan-accent);
  --dhr-plan-ease: cubic-bezier(0.2, 0.75, 0.15, 1);
  --dhr-plan-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.6%, 1.067 22.8%, 1.077 26%, 1.058 31%, 1.012 41.2%, 0.996 48.5%, 1.001 60.8%, 1);
  --dhr-plan-mono: ui-monospace, Menlo, Consolas, monospace;
  color-scheme: light;
}

.dhr-plan {
  .dhr-plan-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; color: var(--dhr-plan-muted); }
  .dhr-plan-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .dhr-plan-app {
    display: grid; height: 100%;
    grid-template-columns: 224px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }

  /* ---------- sidebar ---------- */
  .dhr-plan-side {
    grid-area: side; display: flex; flex-direction: column; gap: 18px; min-height: 0; overflow: auto;
    padding: 18px 12px 14px; border-right: 1px solid var(--dhr-plan-line); background: var(--dhr-plan-sunk);
    scrollbar-width: thin;
  }
  .dhr-plan-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dhr-plan-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--dhr-plan-ink); fill: none; stroke: var(--dhr-plan-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dhr-plan-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dhr-plan-brand b { font-size: 14px; font-weight: 680; letter-spacing: -0.01em; }
  .dhr-plan-brand small { font-size: 11px; color: var(--dhr-plan-muted); }

  .dhr-plan-nav { display: grid; gap: 2px; }
  .dhr-plan-nav button {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px;
    color: var(--dhr-plan-muted); font-weight: 560; transition: background-color 160ms, color 160ms;
  }
  .dhr-plan-nav button:hover { color: var(--dhr-plan-ink); background: color-mix(in oklch, var(--dhr-plan-ink) 5%, transparent); }
  .dhr-plan-nav button[aria-current="page"] { color: var(--dhr-plan-ink); background: var(--dhr-plan-card); box-shadow: 0 1px 0 var(--dhr-plan-line), 0 0 0 1px var(--dhr-plan-line); }
  .dhr-plan-nav svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhr-plan-nav span { flex: 1; }
  .dhr-plan-count { font: 600 11px var(--dhr-plan-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; background: color-mix(in oklch, var(--dhr-plan-accent) 14%, transparent); color: color-mix(in oklch, var(--dhr-plan-accent), var(--dhr-plan-ink) 35%); font-variant-numeric: tabular-nums; }

  .dhr-plan-sidehead { display: flex; align-items: baseline; justify-content: space-between; padding: 0 6px 6px; }
  .dhr-plan-link { font-size: 11.5px; font-weight: 600; color: color-mix(in oklch, var(--dhr-plan-accent), var(--dhr-plan-ink) 25%); border-radius: 4px; }
  .dhr-plan-link:hover { text-decoration: underline; text-underline-offset: 3px; }
  .dhr-plan-link[aria-disabled="true"] { color: var(--dhr-plan-faint); text-decoration: none; }
  .dhr-plan-dlist { display: grid; gap: 1px; }
  .dhr-plan-dept {
    width: 100%; display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; align-items: center; gap: 9px;
    padding: 6px 8px; border-radius: 8px; transition: background-color 160ms, color 160ms;
  }
  .dhr-plan-dept:hover { background: color-mix(in oklch, var(--dhr-plan-ink) 5%, transparent); }
  .dhr-plan-dept i { width: 12px; height: 12px; border-radius: 4px; background: var(--c); box-shadow: inset 0 0 0 1.5px var(--c); transition: background-color 200ms, scale 300ms var(--dhr-plan-spring); }
  .dhr-plan-dept span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-plan-dept b { font: 500 11.5px var(--dhr-plan-mono); color: var(--dhr-plan-muted); font-variant-numeric: tabular-nums; }
  .dhr-plan-dept[aria-pressed="false"] { color: var(--dhr-plan-faint); }
  .dhr-plan-dept[aria-pressed="false"] i { background: transparent; scale: 0.82; }
  .dhr-plan-dept[aria-disabled="true"] { cursor: default; }
  .dhr-plan-planver { margin-top: auto; display: grid; gap: 6px; padding: 12px 6px 0; border-top: 1px solid var(--dhr-plan-line); }
  .dhr-plan-select {
    width: 100%; padding: 7px 9px; border-radius: 8px; border: 1px solid var(--dhr-plan-line2); background: var(--dhr-plan-card);
    font-size: 12px; font-weight: 560;
  }

  /* ---------- header ---------- */
  .dhr-plan-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 18px 20px 14px; }
  .dhr-plan-title { display: grid; gap: 3px; min-width: 0; }
  .dhr-plan-title h2 { font-size: clamp(17px, 1.9cqi, 23px); font-weight: 700; letter-spacing: -0.022em; line-height: 1.15; }
  .dhr-plan-range, .dhr-plan-stagef {
    position: relative; display: flex; padding: 3px; border-radius: 10px; background: var(--dhr-plan-sunk); box-shadow: inset 0 0 0 1px var(--dhr-plan-line);
    flex: none;
  }
  .dhr-plan-range button, .dhr-plan-stagef button {
    position: relative; z-index: 1; padding: 5px 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dhr-plan-muted);
    white-space: nowrap; transition: color 200ms;
  }
  .dhr-plan-range button:hover, .dhr-plan-stagef button:hover { color: var(--dhr-plan-ink); }
  .dhr-plan-range [aria-checked="true"], .dhr-plan-stagef [aria-checked="true"] { color: var(--dhr-plan-ink); }
  .dhr-plan-thumb {
    position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; width: var(--w, 0px); translate: var(--x, 0px) 0;
    border-radius: 7px; background: var(--dhr-plan-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dhr-plan-ink) 14%, transparent), 0 0 0 1px var(--dhr-plan-line);
    transition: translate 520ms var(--dhr-plan-spring), width 520ms var(--dhr-plan-spring);
  }

  /* ---------- main ---------- */
  .dhr-plan-main { grid-area: main; min-height: 0; overflow: auto; padding: 2px 20px 20px; scrollbar-width: thin; }
  .dhr-plan-view { animation: dhr-plan-rise 380ms var(--dhr-plan-ease) both; }
  .dhr-plan-ov { display: grid; gap: 14px; height: 100%; min-height: 540px; grid-template-rows: auto minmax(190px, 1.1fr) minmax(196px, 1fr); }
  .dhr-plan-card {
    display: flex; flex-direction: column; min-height: 0; min-width: 0; margin: 0;
    padding: 12px 14px; border-radius: 12px; background: var(--dhr-plan-card);
    box-shadow: 0 0 0 1px var(--dhr-plan-line), 0 1px 2px color-mix(in oklch, var(--dhr-plan-ink) 5%, transparent);
  }
  .dhr-plan-cardhead { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
  .dhr-plan-cardhead h3 { font-size: 13px; font-weight: 680; letter-spacing: -0.005em; }
  .dhr-plan-cardnote { font-size: 11.5px; color: var(--dhr-plan-muted); text-align: right; }
  .dhr-plan-key { display: flex; gap: 14px; font-size: 11.5px; color: var(--dhr-plan-muted); }
  .dhr-plan-key li { display: flex; align-items: center; gap: 6px; }
  .dhr-plan-key i { width: 14px; height: 10px; border-radius: 3px; }
  .dhr-plan-k-act { background: linear-gradient(90deg, var(--dhr-plan-eng) 0 34%, var(--dhr-plan-pd) 0 52%, var(--dhr-plan-sal) 0 76%, var(--dhr-plan-cs) 0); }
  .dhr-plan-k-fc { background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dhr-plan-eng) 55%, var(--dhr-plan-card)) 0 2px, var(--dhr-plan-card) 0 4px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dhr-plan-eng) 50%, transparent); }
  .dhr-plan-k-plan { height: 0 !important; border-top: 2px solid var(--dhr-plan-plan); border-radius: 0 !important; }
  .dhr-plan-k-hire { background: var(--dhr-plan-accent); }
  .dhr-plan-k-exit { background: var(--dhr-plan-neg); }
  .dhr-plan-k-net { height: 0 !important; border-top: 2px solid var(--dhr-plan-ink); border-radius: 0 !important; }

  /* ---------- KPIs (integers count up through a registered custom property) ---------- */
  .dhr-plan-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; border-radius: 12px; background: var(--dhr-plan-card); box-shadow: 0 0 0 1px var(--dhr-plan-line); }
  .dhr-plan-kpi { display: grid; align-content: start; gap: 2px; padding: 12px 16px 12px; min-width: 0; }
  .dhr-plan-kpi + .dhr-plan-kpi { box-shadow: -1px 0 0 var(--dhr-plan-line); }
  .dhr-plan-kpi dt { font-size: 11.5px; font-weight: 600; color: var(--dhr-plan-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-plan-figure { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
  .dhr-plan-big {
    font-size: clamp(22px, 2.5cqi, 30px); font-weight: 650; letter-spacing: -0.03em; line-height: 1.1; font-variant-numeric: tabular-nums;
    counter-reset: dhr-plann var(--dhr-plan-n); transition: --dhr-plan-n 1000ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .dhr-plan-big::after { content: counter(dhr-plann); }
  .dhr-plan-big[data-sign="+"]::before { content: "+"; }
  .dhr-plan-big[data-sign="-"]::before { content: "\2212"; }
  .dhr-plan-delta { font-size: 11.5px; font-weight: 650; padding: 1px 7px; border-radius: 99px; font-variant-numeric: tabular-nums; white-space: nowrap; background: var(--dhr-plan-sunk); color: var(--dhr-plan-muted); }
  .dhr-plan-delta[data-tone="pos"] { background: color-mix(in oklch, var(--dhr-plan-pos) 13%, transparent); color: color-mix(in oklch, var(--dhr-plan-pos), var(--dhr-plan-ink) 30%); }
  .dhr-plan-delta[data-tone="neg"] { background: color-mix(in oklch, var(--dhr-plan-neg) 13%, transparent); color: color-mix(in oklch, var(--dhr-plan-neg), var(--dhr-plan-ink) 25%); }
  .dhr-plan-sub { font-size: 11.5px; color: var(--dhr-plan-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  /* ---------- charts ---------- */
  .dhr-plan-plot { position: relative; flex: 1; min-height: 150px; border-radius: 6px; cursor: crosshair; }
  .dhr-plan-plot:focus-visible { outline-offset: 4px; }
  .dhr-plan-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible; font: 500 10.5px system-ui, sans-serif; }
  .dhr-plan-svg text { fill: var(--dhr-plan-muted); font-variant-numeric: tabular-nums; }
  .dhr-plan-grid line { stroke: var(--dhr-plan-line); }
  .dhr-plan-grid .is-base { stroke: var(--dhr-plan-line2); }
  .dhr-plan-seg { transition: opacity 260ms; }
  .dhr-plan-seg.is-fc { opacity: 0.62; }
  .dhr-plan-seg.is-out, .dhr-plan-hatch.is-out, .dhr-plan-fbar.is-out { opacity: 0.28; }
  .dhr-plan-planline { fill: none; stroke: var(--dhr-plan-plan); stroke-width: 2; stroke-linejoin: round; stroke-dasharray: 1; animation: dhr-plan-draw 1100ms var(--dhr-plan-ease) 150ms both; }
  .dhr-plan-planline.is-fc { stroke-dasharray: 0.012 0.01; animation: none; opacity: 0.7; }
  .dhr-plan-today line { stroke: var(--dhr-plan-ink); stroke-dasharray: 2 3; opacity: 0.45; }
  .dhr-plan-today text { fill: var(--dhr-plan-ink); font-weight: 650; font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }
  .dhr-plan-band { fill: color-mix(in oklch, var(--dhr-plan-accent) 5%, transparent); transition: opacity 300ms; }
  .dhr-plan-cross { fill: color-mix(in oklch, var(--dhr-plan-ink) 6%, transparent); pointer-events: none; transition: opacity 150ms; }
  .dhr-plan-wf { transition: opacity 200ms; }
  .dhr-plan-wf.is-open, .dhr-plan-wf.is-close { fill: var(--dhr-plan-plan); }
  .dhr-plan-wf.is-open { fill: color-mix(in oklch, var(--dhr-plan-plan) 55%, var(--dhr-plan-card)); }
  .dhr-plan-wf.is-hire { fill: var(--dhr-plan-accent); }
  .dhr-plan-wf.is-exit { fill: var(--dhr-plan-neg); }
  .dhr-plan-wf.is-xfer { fill: var(--dhr-plan-cs); }
  .dhr-plan-conn { stroke: var(--dhr-plan-line2); stroke-dasharray: 2 2; }
  .dhr-plan-wf.is-plan { fill: color-mix(in oklch, var(--dhr-plan-plan) 6%, transparent); stroke: var(--dhr-plan-plan); stroke-width: 1.2; stroke-dasharray: 3 2.5; }
  .dhr-plan-gap { font-size: 10.5px; font-weight: 650; fill: var(--dhr-plan-muted) !important; }
  .dhr-plan-gap[data-tone="neg"] { fill: var(--dhr-plan-neg) !important; }
  .dhr-plan-gap[data-tone="pos"] { fill: color-mix(in oklch, var(--dhr-plan-pos), var(--dhr-plan-ink) 20%) !important; }
  .dhr-plan-vlabel { fill: var(--dhr-plan-ink) !important; font-weight: 650; font-size: 11px; }
  .dhr-plan-break { fill: none; stroke: var(--dhr-plan-card); stroke-width: 3; }
  .dhr-plan-fbar.is-hire { fill: var(--dhr-plan-accent); }
  .dhr-plan-fbar.is-exit { fill: var(--dhr-plan-neg); }
  .dhr-plan-fbar.is-fc { fill-opacity: 0.45; }
  .dhr-plan-netline { fill: none; stroke: var(--dhr-plan-ink); stroke-width: 1.6; stroke-linejoin: round; stroke-dasharray: 1; animation: dhr-plan-draw 1000ms var(--dhr-plan-ease) 200ms both; }
  .dhr-plan-netdot { fill: var(--dhr-plan-card); stroke: var(--dhr-plan-ink); stroke-width: 1.5; }
  .dhr-plan-tip {
    position: absolute; left: 0; top: 0; z-index: 5; min-width: 168px; max-width: 240px; padding: 9px 11px; border-radius: 9px;
    background: var(--dhr-plan-ink); color: var(--dhr-plan-bg); font-size: 11.5px; line-height: 1.35; pointer-events: none;
    box-shadow: 0 12px 28px -10px color-mix(in oklch, var(--dhr-plan-ink) 60%, transparent);
    transition: translate 120ms var(--dhr-plan-ease);
  }
  .dhr-plan-tip b { display: block; font-size: 12px; margin-bottom: 5px; }
  .dhr-plan-tip b small { font-weight: 500; opacity: 0.65; margin-left: 4px; }
  .dhr-plan-tip dl { display: grid; grid-template-columns: 10px 1fr auto; gap: 3px 7px; align-items: center; }
  .dhr-plan-tip dt i { display: block; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  .dhr-plan-tip dd { font-variant-numeric: tabular-nums; text-align: right; font-weight: 600; }
  .dhr-plan-tip .is-sum { grid-column: 1 / -1; height: 1px; background: color-mix(in oklch, var(--dhr-plan-bg) 22%, transparent); margin: 3px 0; }
  .dhr-plan-tip .t-neg { color: color-mix(in oklch, var(--dhr-plan-neg), white 40%); }
  .dhr-plan-tip .t-pos { color: color-mix(in oklch, var(--dhr-plan-accent), white 45%); }

  /* ---------- bridge + variance pair ---------- */
  .dhr-plan-pair { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 14px; min-height: 0; }
  .dhr-plan-vgrid {
    display: grid; align-content: start; overflow: auto; min-height: 0; scrollbar-width: thin;
    grid-template-columns: minmax(104px, 1.4fr) repeat(3, minmax(40px, auto)) minmax(64px, 1fr); column-gap: 12px;
  }
  .dhr-plan-vhead, .dhr-plan-vbody, .dhr-plan-vbody li, .dhr-plan-vrow, .dhr-plan-vtotal { display: grid; grid-template-columns: subgrid; grid-column: 1 / -1; }
  .dhr-plan-vhead { position: sticky; top: 0; z-index: 1; background: var(--dhr-plan-card); padding-bottom: 4px; border-bottom: 1px solid var(--dhr-plan-line); }
  .dhr-plan-vhead button, .dhr-plan-vbarh, .dhr-plan-table th button, .dhr-plan-table th { font-size: 10.5px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dhr-plan-muted); white-space: nowrap; }
  .dhr-plan-vhead span:nth-child(n + 2):not(.dhr-plan-vbarh) { text-align: right; }
  .dhr-plan-vhead button { display: inline-flex; align-items: center; gap: 3px; padding: 3px 0; border-radius: 4px; }
  .dhr-plan-vhead button:hover, .dhr-plan-table th button:hover { color: var(--dhr-plan-ink); }
  [aria-sort="ascending"] > button::after { content: "\2191"; color: var(--dhr-plan-ink); }
  [aria-sort="descending"] > button::after { content: "\2193"; color: var(--dhr-plan-ink); }
  .dhr-plan-vbarh { text-align: center; padding: 3px 0; }
  .dhr-plan-vrow {
    align-items: center; padding: 6px 0; border-radius: 7px; position: relative;
    font-variant-numeric: tabular-nums; transition: background-color 150ms;
  }
  .dhr-plan-vbody li + li .dhr-plan-vrow { box-shadow: 0 -1px 0 var(--dhr-plan-line); }
  .dhr-plan-vrow:hover { background: color-mix(in oklch, var(--dhr-plan-ink) 4%, transparent); }
  .dhr-plan-vrow[aria-pressed="true"] { background: color-mix(in oklch, var(--dhr-plan-accent) 9%, transparent); }
  .dhr-plan-vrow > span { text-align: right; }
  .dhr-plan-vrow > .dhr-plan-vname { text-align: left; display: flex; align-items: center; gap: 8px; min-width: 0; font-weight: 560; }
  .dhr-plan-vname i { flex: none; width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
  .dhr-plan-vname em { font-style: normal; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-plan-vvar { font-weight: 680; }
  .dhr-plan-vvar[data-tone="neg"] { color: var(--dhr-plan-neg); }
  .dhr-plan-vvar[data-tone="pos"] { color: color-mix(in oklch, var(--dhr-plan-pos), var(--dhr-plan-ink) 20%); }
  .dhr-plan-vbar { position: relative; height: 10px; }
  .dhr-plan-vbar::before { content: ""; position: absolute; left: 50%; top: -3px; bottom: -3px; width: 1px; background: var(--dhr-plan-line2); }
  .dhr-plan-vbar i {
