/* actuals, January to September: exits at each department's run rate, hires against plan v3 */
const R = rng(2611);
for (const d of DEPTS) { d.hires = []; d.exits = []; d.hc = []; d.tin = Array(12).fill(0); d.tout = Array(12).fill(0); }
for (const x of XFER) { BY[x.from].tout[x.m]++; BY[x.to].tin[x.m]++; }
for (const d of DEPTS) {
  let hc = d.open;
  for (let m = 0; m <= LAST; m++) {
    const ex = Math.max(0, Math.round(hc * d.rate / 12 + (R() - 0.5) * 1.8));
    const hi = Math.max(0, Math.round(d.v3[m] + ex + d.bias + (R() - 0.5) * 2.2));
    hc += hi - ex + d.tin[m] - d.tout[m];
    d.hires[m] = hi; d.exits[m] = ex; d.hc[m] = hc;
  }
  d.expEx = d.exits.slice(0, LAST + 1).reduce((a, b) => a + b, 0) / (LAST + 1);
}
/* the forecast is probability-weighted: every open role contributes P(stage) in its start month */
function forecast() {
  for (const d of DEPTS) {
    let hc = d.hc[LAST];
    for (let m = LAST + 1; m < 12; m++) {
      const eh = REQS.reduce((s, q) => s + (q.dept === d.id && q.start === m ? P[q.stage] : 0), 0);
      d.hires[m] = eh; d.exits[m] = d.expEx; hc += eh - d.expEx; d.hc[m] = hc;
    }
  }
}
