/* ---------- bridge: opening + hires − exits ± transfers = closing ---------- */
function bridgeModel() {
  const [a, b] = RANGES[S.range], A = act();
  let hi = 0, ex = 0, tn = 0;
  for (let m = a; m <= b; m++) for (const d of A) { hi += d.hires[m]; ex += d.exits[m]; tn += d.tin[m] - d.tout[m]; }
  const open = sum(A.map((d) => hcAt(d, a - 1))), close = sum(A.map((d) => hcAt(d, b))), plan = sum(A.map((d) => planAt(d, b)));
  const lo = Math.min(open, close, plan, open + hi - ex), top = Math.max(open + hi, open, close, plan);
  const span = top - lo, base = Math.max(0, Math.floor((lo - span * 0.9) / 10) * 10);
  const max = Math.ceil((top + span * 0.12) / 5) * 5;
  const M = { open, hi, ex, tn, close, plan, base, max };
