  c.plot.addEventListener('pointerleave', () => { hideTip(c); });
  c.plot.addEventListener('focus', () => { if (!c.target) return; cur = Math.max(0, cur); show(c, cur); });
  c.plot.addEventListener('blur', () => hideTip(c));
