    ? 'Counts as <b>' + P[q.stage].toFixed(2) + '</b> of a hire in ' + START.find((s) => s[0] === q.start)[1] + '. ' + esc(d.name) + ' lands at <b>' + d.hc[11].toFixed(1) + '</b> against a plan of <b>' + planAt(d, 11) + '</b>.'
    : 'Starts after year end, so it adds nothing to the FY26 landing. ' + esc(d.name) + ' lands at <b>' + d.hc[11].toFixed(1) + '</b> against a plan of <b>' + planAt(d, 11) + '</b>.';
  const list = rowsOf(), i = list.findIndex((r) => r.id === q.id);
  $('[data-d="pos"]', drawer).textContent = i < 0 ? 'filtered out' : (i + 1) + ' of ' + list.length;
  const prev = $('[data-act="prev"]', drawer), next = $('[data-act="next"]', drawer);
  const noPrev = i <= 0, noNext = i < 0 || i >= list.length - 1;
  prev.setAttribute('aria-disabled', noPrev); prev.title = noPrev ? 'This is the first role in the list' : 'Previous role';
  next.setAttribute('aria-disabled', noNext); next.title = noNext ? 'This is the last role in the list' : 'Next role';
}

/* ================= render ================= */
const TITLES = { overview: 'Headcount, plan vs actual', moves: 'Hires, exits and transfers', reqs: 'Open roles and the year-end landing' };
function render(anim = true) {
  forecast();
  hideTip(bridge); hideTip(flow);
  paintDepts();
  const [a, b] = RANGES[S.range];
  $('[data-k="eyebrow"]').textContent = 'Workforce plan · FY2026 · ' + RANGES[S.range][2] + ' · actuals to 30 Sep';
  $('[data-k="h2"]').textContent = TITLES[S.view];
  $('[data-k="bridgenote"]').textContent = dateOf(a - 1) + ' → ' + dateOf(b) + (b > LAST ? ' (forecast)' : '');
  $('.dhr-plan-range').hidden = S.view === 'reqs';
  if (S.view === 'overview') {
    paintKpis(); paintVar();
    animateTo(trend, trendModel(), anim ? 620 : 0);
    animateTo(bridge, bridgeModel(), anim ? 620 : 0);
  } else if (S.view === 'moves') {
    paintMoves();
    animateTo(flow, flowModel(), anim ? 620 : 0);
  } else paintReqs();
  if (!drawer.hidden) paintDrawer();
}
function setView(v) {
  if (v === S.view) return;
  S.view = v;
  for (const b of $$('.dhr-plan-nav button')) { if (b.dataset.view === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); }
  for (const s of $$('.dhr-plan-view')) s.hidden = s.dataset.v !== v;
  if (v !== 'reqs') closeReq();
  render();
  $('.dhr-plan-main').scrollTop = 0;
  requestAnimationFrame(() => { if (!root.isConnected) return; thumb($('.dhr-plan-range')); thumb($('.dhr-plan-stagef')); });
}

/* ================= events ================= */
root.addEventListener('click', (e) => {
  const t = e.target.closest('button, tr[data-id]');
  if (!t || !root.contains(t)) return;
  if (t.getAttribute('aria-disabled') === 'true') return;
  if (t.dataset.view) return setView(t.dataset.view);
  if (t.dataset.r) {
    if (S.range === t.dataset.r) return;
    S.range = t.dataset.r;
    for (const b of $$('.dhr-plan-range [role=radio]')) { b.setAttribute('aria-checked', b === t); b.tabIndex = b === t ? 0 : -1; }
    thumb($('.dhr-plan-range'));
    return render();
  }
  if (t.dataset.st) {
    S.stage = t.dataset.st;
    for (const b of $$('.dhr-plan-stagef [role=radio]')) { b.setAttribute('aria-checked', b === t); b.tabIndex = b === t ? 0 : -1; }
    thumb($('.dhr-plan-stagef'));
    return render();
  }
  if (t.classList.contains('dhr-plan-dept')) {
    const id = t.dataset.d;
    if (S.sel.has(id)) S.sel.delete(id); else S.sel.add(id);
    return render();
  }
  if (t.dataset.act === 'all') { S.sel = new Set(DEPTS.map((d) => d.id)); return render(); }
  if (t.classList.contains('dhr-plan-vrow')) {
    const id = t.dataset.d;
    S.sel = S.sel.size === 1 && S.sel.has(id) ? new Set(DEPTS.map((d) => d.id)) : new Set([id]);
    render();
    return toast(S.sel.size === 1 ? 'Showing ' + BY[id].name + ' only' : 'Showing all departments');
  }
  if (t.dataset.sort) {
    const k = t.dataset.sort;
    S.vsort = [k, S.vsort[0] === k ? -S.vsort[1] : (k === 'var' || k === 'name' ? 1 : -1)];
    return paintVar();
  }
  if (t.dataset.rs) {
    const k = t.dataset.rs;
    S.rsort = [k, S.rsort[0] === k ? -S.rsort[1] : (k === 'days' ? -1 : 1)];
    return paintReqs();
  }
  if (t.dataset.id) return openReq(t.dataset.id);
  if (t.dataset.act === 'close') return closeReq();
  if (t.dataset.act === 'prev' || t.dataset.act === 'next') {
    const list = rowsOf(), i = list.findIndex((r) => r.id === S.open), n = list[i + (t.dataset.act === 'next' ? 1 : -1)];
    if (n) openReq(n.id, false);
    return;
  }
  if (t.dataset.setStage || t.dataset.setStart) {
    const q = REQS.find((r) => r.id === S.open), d = BY[q.dept], before = d.hc[11];
    if (t.dataset.setStage) q.stage = t.dataset.setStage; else q.start = +t.dataset.setStart;
    render();
    const focusSel = t.dataset.setStage ? '[data-set-stage="' + q.stage + '"]' : '[data-set-start="' + q.start + '"]';
    const f = $(focusSel, drawer); if (f) f.focus({ preventScroll: true });
    return toast(q.id + (t.dataset.setStage ? ' moved to ' + SNAME[q.stage] : ' now starts ' + START.find((s) => s[0] === q.start)[1]) + ' · ' + d.name + ' landing ' + sgn(d.hc[11] - before, Number.isInteger(+(d.hc[11] - before).toFixed(2)) ? 0 : 2));
  }
});
$('.dhr-plan-select').addEventListener('change', (e) => {
  S.plan = e.target.value;
  render();
  toast('Comparing against plan ' + S.plan + ' · year-end target ' + sum(DEPTS.map((d) => planAt(d, 11))));
});

root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !drawer.hidden) { e.preventDefault(); closeReq(); return; }
  const grp = e.target.closest('[role=radiogroup]');
  if (grp && e.target.getAttribute('role') === 'radio') {
    const step = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key];
    if (!step) return;
    e.preventDefault();
    const items = $$('[role=radio]', grp), i = items.indexOf(e.target), n = items[(i + step + items.length) % items.length];
    n.focus(); n.click();
    return;
  }
  if (e.target.closest('.dhr-plan-nav') && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
    e.preventDefault();
    const items = $$('.dhr-plan-nav button'), i = items.indexOf(e.target.closest('button'));
    items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus();
    return;
  }
  const tr = e.target.closest('tr[data-id]');
  if (tr) {
    const rows = $$('tr[data-id]', tbody), i = rows.indexOf(tr);
    const to = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: rows.length - 1 }[e.key];
    if (to !== undefined) {
      e.preventDefault();
      const n = rows[Math.max(0, Math.min(rows.length - 1, to))];
      rows.forEach((r) => { r.tabIndex = r === n ? 0 : -1; });
      n.focus();
      if (!drawer.hidden) openReq(n.dataset.id, false);
    } else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openReq(tr.dataset.id); }
  }
});

/* ================= mount: draw once the dashboard is actually on screen ================= */
let started = false;
function intro() {
  if (started || !root.isConnected) return;
  started = true;
  render();
  thumb($('.dhr-plan-range')); thumb($('.dhr-plan-stagef'));
}
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((es) => { if (es.some((x) => x.isIntersecting)) { io.disconnect(); intro(); } });
  io.observe(root);
} else intro();
new ResizeObserver(() => { thumb($('.dhr-plan-range')); thumb($('.dhr-plan-stagef')); }).observe(root);

