/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-churn {
  width: 100%;
  height: var(--dhr-churn-h, 680px);
  container-type: inline-size;
  container-name: dhr-churn;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-churn-bg);
  color: var(--dhr-churn-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-churn-accent);
  scrollbar-color: var(--dhr-churn-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-churn-focus, var(--dhr-churn-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@keyframes dhr-churn-in { from { opacity: 0; translate: 0 8px; } }
@keyframes dhr-churn-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhr-churn-grow { from { scale: 0 1; } }
@keyframes dhr-churn-row { from { opacity: 0.2; translate: 0 10px; } }

.dhr-churn {
  /* re-theme: ground, ink, the regretted accent and the rate line */
  --dhr-churn-bg: oklch(0.195 0.008 55);
  --dhr-churn-ink: oklch(0.95 0.012 85);
  --dhr-churn-accent: oklch(0.72 0.16 34);
  --dhr-churn-ttm: oklch(0.88 0.11 98);
  --dhr-churn-sand: color-mix(in oklch, var(--dhr-churn-ink) 52%, oklch(0.7 0.06 70));
  --dhr-churn-g0: oklch(0.88 0.05 85);
  --dhr-churn-g1: oklch(0.8 0.1 65);
  --dhr-churn-g2: oklch(0.72 0.14 45);
  --dhr-churn-g3: oklch(0.66 0.17 28);
  --dhr-churn-d0: oklch(0.78 0.11 200);
  --dhr-churn-d1: oklch(0.72 0.16 34);
  --dhr-churn-d2: oklch(0.84 0.12 95);
  --dhr-churn-d3: oklch(0.72 0.1 150);
  --dhr-churn-d4: oklch(0.7 0.11 300);
  --dhr-churn-d5: oklch(0.8 0.05 60);

  --dhr-churn-card: color-mix(in oklch, var(--dhr-churn-bg), var(--dhr-churn-ink) 4.5%);
  --dhr-churn-raise: color-mix(in oklch, var(--dhr-churn-bg), var(--dhr-churn-ink) 9%);
  --dhr-churn-sunk: color-mix(in oklch, var(--dhr-churn-bg), black 25%);
  --dhr-churn-line: color-mix(in oklch, var(--dhr-churn-ink) 9%, transparent);
  --dhr-churn-line2: color-mix(in oklch, var(--dhr-churn-ink) 17%, transparent);
  --dhr-churn-muted: color-mix(in oklch, var(--dhr-churn-ink) 62%, var(--dhr-churn-bg));
  --dhr-churn-faint: color-mix(in oklch, var(--dhr-churn-ink) 38%, var(--dhr-churn-bg));
  --dhr-churn-good: oklch(0.8 0.13 155);
  --dhr-churn-ease: cubic-bezier(0.22, 0.8, 0.2, 1);
  --dhr-churn-spring: linear(0, 0.01, 0.04 2.2%, 0.16 4.8%, 0.74 13.4%, 0.95 17.4%, 1.03 20.4%, 1.07 23.6%, 1.075 26.8%, 1.05 32%, 1.01 42%, 0.995 50%, 1);
  --dhr-churn-mono: ui-monospace, Menlo, Consolas, monospace;
  color-scheme: dark;
}

.dhr-churn {
  .dhr-churn-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhr-churn-muted); }
  .dhr-churn-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .dhr-churn-app {
    display: grid; height: 100%;
    grid-template-columns: 78px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "rail head" "rail main";
  }

  /* ---------- icon rail ---------- */
  .dhr-churn-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 16px 8px; background: var(--dhr-churn-sunk); border-right: 1px solid var(--dhr-churn-line); }
  .dhr-churn-mark { display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 14px; border-radius: 12px; background: color-mix(in oklch, var(--dhr-churn-accent) 18%, transparent); }
  .dhr-churn-mark svg { width: 22px; height: 22px; fill: none; stroke: var(--dhr-churn-accent); stroke-width: 1.8; stroke-linecap: round; }
  .dhr-churn-rail button {
    position: relative; width: 60px; display: grid; justify-items: center; gap: 4px; padding: 9px 2px 7px; border-radius: 12px;
    color: var(--dhr-churn-muted); font-size: 10.5px; font-weight: 600; letter-spacing: 0.01em; transition: color 160ms, background-color 160ms;
  }
  .dhr-churn-rail button svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dhr-churn-rail button:hover { color: var(--dhr-churn-ink); background: color-mix(in oklch, var(--dhr-churn-ink) 6%, transparent); }
  .dhr-churn-rail button[aria-current="page"] { color: var(--dhr-churn-ink); background: var(--dhr-churn-raise); }
  .dhr-churn-rail button[aria-current="page"]::before { content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dhr-churn-accent); }

  /* ---------- header ---------- */
  .dhr-churn-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 18px 22px 14px; }
  .dhr-churn-title { display: grid; gap: 4px; min-width: 0; }
  .dhr-churn-title h2 { font-size: clamp(19px, 2.2cqi, 27px); font-weight: 700; letter-spacing: -0.028em; line-height: 1.1; }
  .dhr-churn-controls { display: flex; align-items: center; gap: 10px; flex: none; }
  .dhr-churn-menuwrap { position: relative; }
  .dhr-churn-menubtn {
    display: grid; grid-template-columns: auto 16px; grid-template-areas: "l i" "v i"; align-items: center; column-gap: 10px;
    padding: 6px 10px 6px 12px; border-radius: 10px; background: var(--dhr-churn-card); box-shadow: inset 0 0 0 1px var(--dhr-churn-line2); text-align: left;
    transition: box-shadow 160ms, background-color 160ms;
  }
  .dhr-churn-menubtn:hover, .dhr-churn-menubtn[aria-expanded="true"] { background: var(--dhr-churn-raise); }
  .dhr-churn-mlabel { grid-area: l; font-size: 9.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhr-churn-muted); }
  .dhr-churn-menubtn b { grid-area: v; font-size: 12.5px; font-weight: 620; min-width: 118px; }
  .dhr-churn-menubtn svg { grid-area: i; width: 16px; height: 16px; fill: none; stroke: var(--dhr-churn-muted); stroke-width: 2; stroke-linecap: round; transition: rotate 300ms var(--dhr-churn-spring); }
  .dhr-churn-menubtn[aria-expanded="true"] svg { rotate: 180deg; }
  .dhr-churn-menu {
    position: absolute; z-index: 40; top: calc(100% + 6px); right: 0; min-width: 236px; padding: 5px; border-radius: 12px;
    background: var(--dhr-churn-raise); box-shadow: 0 0 0 1px var(--dhr-churn-line2), 0 22px 44px -16px oklch(0 0 0 / 0.7);
    transform-origin: top right; transition: opacity 180ms, scale 300ms var(--dhr-churn-spring);
  }
  @starting-style { .dhr-churn-menu { opacity: 0; scale: 0.94; } }
  .dhr-churn-menu li {
    display: grid; grid-template-columns: 16px 1fr auto; align-items: center; gap: 9px; padding: 7px 9px; border-radius: 8px;
    cursor: pointer; font-size: 12.5px; color: var(--dhr-churn-ink);
  }
  .dhr-churn-menu li:hover, .dhr-churn-menu li.is-active { background: color-mix(in oklch, var(--dhr-churn-ink) 8%, transparent); }
  .dhr-churn-menu li svg { width: 14px; height: 14px; fill: none; stroke: var(--dhr-churn-accent); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; opacity: 0; }
  .dhr-churn-menu li[aria-selected="true"] svg { opacity: 1; }
  .dhr-churn-menu li em { font: 500 11px var(--dhr-churn-mono); font-style: normal; color: var(--dhr-churn-muted); font-variant-numeric: tabular-nums; }
  .dhr-churn-seg { position: relative; display: flex; padding: 3px; border-radius: 10px; background: var(--dhr-churn-sunk); box-shadow: inset 0 0 0 1px var(--dhr-churn-line); }
  .dhr-churn-seg button { position: relative; z-index: 1; padding: 7px 12px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dhr-churn-muted); white-space: nowrap; transition: color 200ms; }
  .dhr-churn-seg button:hover { color: var(--dhr-churn-ink); }
  .dhr-churn-seg [aria-checked="true"] { color: var(--dhr-churn-bg); }
  .dhr-churn-seg-sm button { padding: 5px 10px; font-size: 11.5px; }
  .dhr-churn-thumb {
    position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; width: var(--w, 0px); translate: var(--x, 0px) 0; border-radius: 7px;
    background: var(--dhr-churn-ink); transition: translate 480ms var(--dhr-churn-spring), width 480ms var(--dhr-churn-spring);
  }

  /* ---------- main + cards ---------- */
  .dhr-churn-main { grid-area: main; min-height: 0; overflow: auto; padding: 0 22px 20px; scrollbar-width: thin; }
  .dhr-churn-view { animation: dhr-churn-in 420ms var(--dhr-churn-ease) both; }
  .dhr-churn-card {
    display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0; padding: 13px 15px;
    border-radius: 14px; background: var(--dhr-churn-card); box-shadow: inset 0 0 0 1px var(--dhr-churn-line);
  }
  .dhr-churn-cardhead { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
  .dhr-churn-cardhead h3 { font-size: 13px; font-weight: 680; letter-spacing: -0.005em; }
  .dhr-churn-cardhead h3 span { font-weight: 500; color: var(--dhr-churn-muted); margin-left: 6px; }
  .dhr-churn-cardnote { font-size: 11.5px; color: var(--dhr-churn-muted); font-weight: 500; }
  .dhr-churn-key { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dhr-churn-muted); }
  .dhr-churn-key li { display: flex; align-items: center; gap: 6px; }
  .dhr-churn-key i { width: 10px; height: 10px; border-radius: 3px; }
  .dhr-churn-k-reg { background: var(--dhr-churn-accent); }
  .dhr-churn-k-non { background: var(--dhr-churn-sand); }
  .dhr-churn-k-ttm { width: 16px !important; height: 0 !important; border-top: 2px solid var(--dhr-churn-ttm); border-radius: 0 !important; }

  .dhr-churn-ov {
    display: grid; gap: 14px; height: 100%; min-height: 520px;
    grid-template-columns: minmax(0, 1.45fr) minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-areas: "kpis kpis" "monthly reasons" "monthly depts";
  }
  .dhr-churn-kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
  .dhr-churn-kpi {
    display: grid; grid-template-columns: 1fr auto; grid-template-areas: "l s" "f s" "c c"; align-items: end; gap: 0 8px;
    padding: 11px 14px 12px; border-radius: 14px; background: var(--dhr-churn-card); box-shadow: inset 0 0 0 1px var(--dhr-churn-line); min-width: 0;
  }
  .dhr-churn-kpi dt { grid-area: l; font-size: 11.5px; font-weight: 600; color: var(--dhr-churn-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-churn-fig { grid-area: f; font-size: clamp(22px, 2.6cqi, 31px); font-weight: 680; letter-spacing: -0.035em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  .dhr-churn-fig small { font-size: 0.5em; font-weight: 600; letter-spacing: 0; color: var(--dhr-churn-muted); margin-left: 3px; }
  .dhr-churn-cmp { grid-area: c; margin-top: 3px; font-size: 11.5px; color: var(--dhr-churn-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-churn-cmp b { font-weight: 650; }
  .dhr-churn-cmp b[data-tone="good"] { color: var(--dhr-churn-good); }
  .dhr-churn-cmp b[data-tone="bad"] { color: var(--dhr-churn-accent); }
  .dhr-churn-spark { grid-area: s; align-self: center; width: 76px; height: 34px; }
  .dhr-churn-spark svg { width: 100%; height: 100%; overflow: visible; }
