css:
/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-funnel {
  width: 100%;
  height: var(--dhr-funnel-h, 680px);
  container-type: inline-size;
  container-name: dhr-funnel;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-funnel-bg);
  color: var(--dhr-funnel-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-funnel-accent);
  scrollbar-color: var(--dhr-funnel-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-funnel-focus, var(--dhr-funnel-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@keyframes dhr-funnel-reveal { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dhr-funnel-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-funnel-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dhr-funnel-fade { from { opacity: 0; } }
@keyframes dhr-funnel-ping { from { opacity: 0.55; scale: 1; } to { opacity: 0; scale: 2.8; } }

.dhr-funnel {
  /* re-theme: paper, ink, the flow colour and the drop-off colour */
  --dhr-funnel-bg: oklch(0.972 0.014 82);
  --dhr-funnel-ink: oklch(0.25 0.022 45);
  --dhr-funnel-accent: oklch(0.66 0.17 40);
  --dhr-funnel-drop: oklch(0.78 0.025 65);
  --dhr-funnel-s-ref: oklch(0.55 0.12 160);
  --dhr-funnel-s-inb: oklch(0.58 0.11 250);
  --dhr-funnel-s-src: oklch(0.72 0.14 78);
  --dhr-funnel-s-agy: oklch(0.56 0.11 330);
  --dhr-funnel-s-cmp: oklch(0.68 0.1 205);

  --dhr-funnel-card: color-mix(in oklch, var(--dhr-funnel-bg), white 70%);
  --dhr-funnel-sunk: color-mix(in oklch, var(--dhr-funnel-bg), var(--dhr-funnel-ink) 4%);
  --dhr-funnel-line: color-mix(in oklch, var(--dhr-funnel-ink) 10%, transparent);
  --dhr-funnel-line2: color-mix(in oklch, var(--dhr-funnel-ink) 19%, transparent);
  --dhr-funnel-muted: color-mix(in oklch, var(--dhr-funnel-ink) 60%, var(--dhr-funnel-bg));
  --dhr-funnel-faint: color-mix(in oklch, var(--dhr-funnel-ink) 38%, var(--dhr-funnel-bg));
  --dhr-funnel-accent-ink: color-mix(in oklch, var(--dhr-funnel-accent), var(--dhr-funnel-ink) 30%);
  --dhr-funnel-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dhr-funnel-spring: linear(0, 0.012, 0.047 2.4%, 0.18 5.1%, 0.75 13.6%, 0.95 17.6%, 1.04 21%, 1.07 24.6%, 1.065 28%, 1.03 34%, 1 44%, 0.995 54%, 1);
  --dhr-funnel-mono: ui-monospace, Menlo, Consolas, monospace;
  color-scheme: light;
}

.dhr-funnel {
  .dhr-funnel-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhr-funnel-muted); }
  .dhr-funnel-app {
    display: grid; height: 100%;
    grid-template-columns: minmax(0, 1fr) 244px;
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "head filters" "main filters";
  }

  /* ---------- header ---------- */
  .dhr-funnel-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; padding: 18px 20px 12px 22px; }
  .dhr-funnel-title { display: grid; gap: 4px; min-width: 0; }
  .dhr-funnel-title .dhr-funnel-eyebrow { display: flex; align-items: center; gap: 8px; }
  .dhr-funnel-dot { position: relative; width: 8px; height: 8px; border-radius: 50%; background: var(--dhr-funnel-accent); }
  .dhr-funnel-dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: var(--dhr-funnel-accent); animation: dhr-funnel-ping 2.2s var(--dhr-funnel-ease) 600ms 3 both; }
  .dhr-funnel-title h2 { font-size: clamp(19px, 2.3cqi, 28px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.08; }
  .dhr-funnel-title h2 em { font-style: normal; font-weight: 500; color: var(--dhr-funnel-accent-ink); letter-spacing: -0.02em; margin-left: 4px; }
  .dhr-funnel-headctl { display: flex; align-items: center; gap: 8px; }
  .dhr-funnel-qs { position: relative; display: flex; padding: 3px; border-radius: 99px; background: var(--dhr-funnel-sunk); box-shadow: inset 0 0 0 1px var(--dhr-funnel-line); }
  .dhr-funnel-qs button { position: relative; z-index: 1; padding: 6px 12px; border-radius: 99px; font-size: 12px; font-weight: 620; color: var(--dhr-funnel-muted); white-space: nowrap; transition: color 200ms; }
  .dhr-funnel-qs button:hover { color: var(--dhr-funnel-ink); }
  .dhr-funnel-qs [aria-checked="true"] { color: white; }
  .dhr-funnel-thumb { position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; width: var(--w, 0px); translate: var(--x, 0px) 0; border-radius: 99px; background: var(--dhr-funnel-accent); box-shadow: 0 2px 8px -2px color-mix(in oklch, var(--dhr-funnel-accent) 60%, transparent); transition: translate 500ms var(--dhr-funnel-spring), width 500ms var(--dhr-funnel-spring); }
  .dhr-funnel-ftoggle { display: none; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 99px; font-size: 12px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--dhr-funnel-line2); background: var(--dhr-funnel-card); }
  .dhr-funnel-ftoggle svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dhr-funnel-ftoggle b { min-width: 17px; height: 17px; padding: 0 4px; border-radius: 99px; background: var(--dhr-funnel-accent); color: white; font-size: 10.5px; display: inline-grid; place-items: center; }
  .dhr-funnel-ftoggle[aria-expanded="true"] { background: var(--dhr-funnel-ink); color: var(--dhr-funnel-bg); }

  /* ---------- main ---------- */
  .dhr-funnel-main {
    grid-area: main; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 0 16px 16px 22px;
    display: grid; gap: 12px; grid-template-rows: auto minmax(214px, 1fr) minmax(232px, 1.12fr);
  }
  .dhr-funnel-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; padding: 2px 0 4px; }
  .dhr-funnel-kpis > div { display: grid; align-content: start; gap: 1px; padding: 0 16px; min-width: 0; }
  .dhr-funnel-kpis > div:first-child { padding-left: 0; }
  .dhr-funnel-kpis > div + div { border-left: 1px solid var(--dhr-funnel-line2); }
  .dhr-funnel-kpis dt { font-size: 11.5px; font-weight: 600; color: var(--dhr-funnel-muted); }
  .dhr-funnel-kpis dd:not(.dhr-funnel-sub) { font-size: clamp(21px, 2.4cqi, 28px); font-weight: 680; letter-spacing: -0.03em; line-height: 1.15; font-variant-numeric: tabular-nums; }
  .dhr-funnel-kpis dd small { font-size: 0.55em; font-weight: 600; letter-spacing: 0; color: var(--dhr-funnel-muted); margin-left: 2px; }
  .dhr-funnel-sub { font-size: 11.5px; color: var(--dhr-funnel-muted); font-variant-numeric: tabular-nums; overflow: hidden; display: flex; flex-wrap: wrap; align-items: center; gap: 0 7px; }
  .dhr-funnel-sub b { font-weight: 650; color: var(--dhr-funnel-ink); }
  .dhr-funnel-sub b[data-tone="up"] { color: oklch(0.5 0.12 155); }
  .dhr-funnel-sub b[data-tone="down"] { color: var(--dhr-funnel-accent-ink); }
  .dhr-funnel-meter { flex: none; width: 64px; height: 6px; border-radius: 3px; background: var(--dhr-funnel-line); overflow: hidden; }
  .dhr-funnel-meter i { display: block; height: 100%; width: calc(var(--v, 0) * 100%); border-radius: 3px; background: var(--dhr-funnel-accent); transition: width 700ms var(--dhr-funnel-ease); }

  .dhr-funnel-card { display: flex; flex-direction: column; min-width: 0; min-height: 0; padding: 12px 14px; border-radius: 14px; background: var(--dhr-funnel-card); box-shadow: 0 0 0 1px var(--dhr-funnel-line), 0 1px 3px color-mix(in oklch, var(--dhr-funnel-ink) 5%, transparent); }
  .dhr-funnel-cardhead { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 6px; }
  .dhr-funnel-cardhead h3 { font-size: 13px; font-weight: 680; }
  .dhr-funnel-cardnote { font-size: 11.5px; color: var(--dhr-funnel-muted); text-align: right; }

  /* ---------- the funnel ---------- */
  .dhr-funnel-flow { position: relative; flex: 1; min-height: 180px; }
  .dhr-funnel-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; font: 500 10.5px system-ui, sans-serif; }
  .dhr-funnel-svg text { fill: var(--dhr-funnel-muted); font-variant-numeric: tabular-nums; }
  .dhr-funnel-flow .dhr-funnel-svg { animation: dhr-funnel-reveal 1100ms var(--dhr-funnel-ease) both; }
  .dhr-funnel-ribbon { transition: opacity 220ms; }
  .dhr-funnel-col { fill: var(--dhr-funnel-accent); transition: opacity 220ms; }
  .dhr-funnel-dropr { fill: var(--dhr-funnel-drop); opacity: 0.55; transition: opacity 220ms; }
  .dhr-funnel-sink { fill: var(--dhr-funnel-drop); }
  .dhr-funnel-brk { fill: none; stroke: var(--dhr-funnel-card); stroke-width: 3.5; }
  .dhr-funnel-conv { font-weight: 700 !important; fill: var(--dhr-funnel-accent-ink) !important; font-size: 11px !important; }
  .dhr-funnel-convbg { fill: var(--dhr-funnel-card); stroke: color-mix(in oklch, var(--dhr-funnel-accent) 35%, transparent); }
  .dhr-funnel-droplab { font-size: 10.5px; }
  .dhr-funnel-droplab .is-n { fill: var(--dhr-funnel-ink) !important; font-weight: 650; }
  .dhr-funnel-flow[data-sel] .dhr-funnel-ribbon, .dhr-funnel-flow[data-sel] .dhr-funnel-col, .dhr-funnel-flow[data-sel] .dhr-funnel-dropr { opacity: 0.4; }
  .dhr-funnel-flow[data-sel] .is-on { opacity: 1 !important; }
  .dhr-funnel-flow[data-sel] .dhr-funnel-dropr.is-on { opacity: 0.75 !important; }
  .dhr-funnel-stages { position: absolute; inset: 0; pointer-events: none; }
  .dhr-funnel-stages button {
    position: absolute; top: 0; pointer-events: auto; display: grid; justify-items: center; align-content: start; gap: 0; padding-top: 0;
    border-radius: 10px; text-align: center; transition: background-color 180ms;
  }
  .dhr-funnel-stages button:hover { background: color-mix(in oklch, var(--dhr-funnel-accent) 6%, transparent); }
  .dhr-funnel-stages button[aria-selected="true"] { background: color-mix(in oklch, var(--dhr-funnel-accent) 9%, transparent); }
  .dhr-funnel-stages button span { font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dhr-funnel-muted); }
  .dhr-funnel-stages button[aria-selected="true"] span { color: var(--dhr-funnel-accent-ink); }
  .dhr-funnel-stages button b { font-size: 15px; font-weight: 720; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  .dhr-funnel-stages button:focus-visible { outline-offset: -2px; }
  .is-tight .dhr-funnel-stages button span { font-size: 9.5px; letter-spacing: 0.02em; }
  .is-tight .dhr-funnel-stages button b { font-size: 12.5px; }
  .is-tight .dhr-funnel-conv { font-size: 9.5px !important; }
  .dhr-funnel-tip {
    position: absolute; left: 0; top: 0; z-index: 8; max-width: 240px; padding: 8px 11px; border-radius: 10px; pointer-events: none;
    background: var(--dhr-funnel-ink); color: var(--dhr-funnel-bg); font-size: 11.5px; line-height: 1.4; box-shadow: 0 14px 28px -12px color-mix(in oklch, var(--dhr-funnel-ink) 60%, transparent);
    transition: translate 110ms var(--dhr-funnel-ease);
  }
  .dhr-funnel-tip b { display: block; font-size: 12px; }
  .dhr-funnel-tip span { opacity: 0.7; }

  /* ---------- lower row ---------- */
  .dhr-funnel-lower { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 12px; min-height: 0; }
  .dhr-funnel-spbody { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr); gap: 16px; }
  .dhr-funnel-mini { font-size: 11.5px; color: var(--dhr-funnel-muted); margin-bottom: 7px; }
  .dhr-funnel-mini b { color: var(--dhr-funnel-ink); font-weight: 650; }
  .dhr-funnel-srcbars { display: grid; gap: 7px; }
  .dhr-funnel-srcbars li { display: grid; grid-template-columns: 62px minmax(0, 1fr) 38px; align-items: center; gap: 8px; font-size: 11.5px; animation: dhr-funnel-in 340ms var(--dhr-funnel-ease) calc(var(--i) * 40ms) both; }
  .dhr-funnel-srcbars li > span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-funnel-srcbars i { height: 8px; border-radius: 4px; background: linear-gradient(90deg, var(--c) calc(var(--v) * 100%), var(--dhr-funnel-line) 0); transition: background 500ms; }
  .dhr-funnel-srcbars b { font: 600 11px var(--dhr-funnel-mono); text-align: right; font-variant-numeric: tabular-nums; }
  .dhr-funnel-srcbars li.is-off { opacity: 0.4; }
  .dhr-funnel-now { min-height: 0; display: flex; flex-direction: column; }
  .dhr-funnel-people { overflow: auto; min-height: 0; flex: 1; scrollbar-width: thin; display: grid; align-content: start; }
  .dhr-funnel-people li { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto auto; align-items: center; gap: 9px; padding: 6px 0; border-top: 1px solid var(--dhr-funnel-line); animation: dhr-funnel-in 320ms var(--dhr-funnel-ease) calc(var(--i) * 35ms) both; }
  .dhr-funnel-people .dhr-funnel-av { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; font-size: 10px; font-weight: 700; color: white; background: var(--c); }
  .dhr-funnel-people p { display: grid; line-height: 1.25; min-width: 0; }
  .dhr-funnel-people p b { font-size: 12px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-funnel-people p small { font-size: 11px; color: var(--dhr-funnel-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-funnel-days { font: 650 11px var(--dhr-funnel-mono); font-style: normal; font-variant-numeric: tabular-nums; color: var(--dhr-funnel-muted); }
  .dhr-funnel-days[data-late] { color: var(--dhr-funnel-accent-ink); }
  .dhr-funnel-nudge { padding: 4px 9px; border-radius: 99px; font-size: 11px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dhr-funnel-line2); transition: background-color 160ms, color 160ms, box-shadow 160ms; white-space: nowrap; }
  .dhr-funnel-nudge:hover:not([aria-disabled="true"]) { background: var(--dhr-funnel-ink); color: var(--dhr-funnel-bg); box-shadow: none; }
  .dhr-funnel-nudge[aria-disabled="true"] { color: oklch(0.5 0.12 155); box-shadow: none; background: color-mix(in oklch, oklch(0.6 0.12 155) 12%, transparent); }
  .dhr-funnel-empty { padding: 14px 0; color: var(--dhr-funnel-muted); font-size: 12px; border: 0 !important; display: block !important; }

  .dhr-funnel-swarm { position: relative; flex: 1; min-height: 150px; cursor: crosshair; border-radius: 8px; }
  .dhr-funnel-row text.is-name { fill: var(--dhr-funnel-ink); font-weight: 620; font-size: 11px; }
  .dhr-funnel-row line { stroke: var(--dhr-funnel-line); }
  .dhr-funnel-dotc { stroke: var(--dhr-funnel-card); stroke-width: 1; animation: dhr-funnel-pop 420ms var(--dhr-funnel-spring) calc(min(var(--i), 90) * 6ms) both; transform-box: fill-box; transform-origin: center; }
  .is-ready .dhr-funnel-dotc { animation: dhr-funnel-fade 260ms var(--dhr-funnel-ease) both; }
  .dhr-funnel-med { stroke: var(--dhr-funnel-ink); stroke-width: 2; stroke-linecap: round; }
  .dhr-funnel-medl { fill: var(--dhr-funnel-ink) !important; font-weight: 650; font-size: 10px; }
  .dhr-funnel-target line { stroke: var(--dhr-funnel-accent); stroke-dasharray: 3 3; stroke-width: 1.2; }
  .dhr-funnel-target text { fill: var(--dhr-funnel-accent-ink) !important; font-weight: 650; }
  .dhr-funnel-ring { fill: none; stroke: var(--dhr-funnel-ink); stroke-width: 2; pointer-events: none; }

  /* ---------- filters ---------- */
  .dhr-funnel-filters {
    grid-area: filters; min-height: 0; overflow: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 18px;
    padding: 18px 16px 16px; background: var(--dhr-funnel-sunk); border-left: 1px solid var(--dhr-funnel-line);
  }
  .dhr-funnel-fsec { display: grid; gap: 7px; }
  .dhr-funnel-fams { display: grid; gap: 1px; }
  .dhr-funnel-fams button { display: grid; grid-template-columns: 16px 1fr auto; align-items: center; gap: 9px; padding: 6px 8px; border-radius: 8px; font-size: 12.5px; font-weight: 560; color: var(--dhr-funnel-muted); transition: background-color 150ms, color 150ms; }
  .dhr-funnel-fams button:hover { background: color-mix(in oklch, var(--dhr-funnel-ink) 5%, transparent); color: var(--dhr-funnel-ink); }
  .dhr-funnel-fams button::before { content: ""; width: 14px; height: 14px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--dhr-funnel-line2); transition: box-shadow 260ms var(--dhr-funnel-spring); }
  .dhr-funnel-fams [aria-checked="true"] { color: var(--dhr-funnel-ink); background: var(--dhr-funnel-card); box-shadow: 0 0 0 1px var(--dhr-funnel-line); }
  .dhr-funnel-fams [aria-checked="true"]::before { box-shadow: inset 0 0 0 4.5px var(--dhr-funnel-accent); }
  .dhr-funnel-fams em { font: 500 11px var(--dhr-funnel-mono); font-style: normal; font-variant-numeric: tabular-nums; }
  .dhr-funnel-srcs { display: flex; flex-wrap: wrap; gap: 6px; }
  .dhr-funnel-srcs button { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px 5px 8px; border-radius: 99px; font-size: 12px; font-weight: 600; background: var(--dhr-funnel-card); box-shadow: inset 0 0 0 1px var(--dhr-funnel-line2); transition: background-color 160ms, color 160ms, box-shadow 160ms; }
  .dhr-funnel-srcs button i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); transition: scale 300ms var(--dhr-funnel-spring), opacity 200ms; }
  .dhr-funnel-srcs button[aria-pressed="false"] { color: var(--dhr-funnel-faint); background: transparent; box-shadow: inset 0 0 0 1px var(--dhr-funnel-line); }
  .dhr-funnel-srcs button[aria-pressed="false"] i { scale: 0.6; opacity: 0.35; }
  .dhr-funnel-srcs button[aria-disabled="true"] { cursor: default; }
  .dhr-funnel-plan p { font-size: 12px; color: var(--dhr-funnel-muted); }
  .dhr-funnel-plan p b { color: var(--dhr-funnel-ink); font-size: 18px; font-weight: 700; letter-spacing: -0.02em; margin-right: 4px; }
  .dhr-funnel-planbars { display: grid; gap: 6px; }
  .dhr-funnel-planbars li { display: grid; grid-template-columns: 76px 1fr 44px; align-items: center; gap: 8px; font-size: 11px; }
  .dhr-funnel-planbars li.is-dim { opacity: 0.4; }
  .dhr-funnel-planbars span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-funnel-planbars i { position: relative; height: 6px; border-radius: 3px; background: var(--dhr-funnel-line); }
  .dhr-funnel-planbars i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(min(var(--v), 1) * 100%); border-radius: 3px; background: var(--dhr-funnel-ink); transition: width 600ms var(--dhr-funnel-ease); }
  .dhr-funnel-planbars i[data-over]::after { background: oklch(0.55 0.12 155); }
  .dhr-funnel-planbars b { font: 600 10.5px var(--dhr-funnel-mono); text-align: right; }
  .dhr-funnel-reset { margin-top: auto; padding: 8px; border-radius: 9px; font-size: 12px; font-weight: 650; text-align: center; box-shadow: inset 0 0 0 1px var(--dhr-funnel-line2); background: var(--dhr-funnel-card); }
  .dhr-funnel-reset:hover:not([aria-disabled="true"]) { background: var(--dhr-funnel-ink); color: var(--dhr-funnel-bg); }
  .dhr-funnel-reset[aria-disabled="true"] { color: var(--dhr-funnel-faint); background: transparent; }

  .dhr-funnel-toast {
    position: absolute; z-index: 30; left: 50%; bottom: 16px; translate: -50% 0; padding: 8px 14px; border-radius: 99px; max-width: calc(100% - 32px);
    background: var(--dhr-funnel-ink); color: var(--dhr-funnel-bg); font-size: 12px; font-weight: 560; opacity: 0; scale: 0.95; pointer-events: none;
    transition: opacity 200ms, scale 360ms var(--dhr-funnel-spring), translate 360ms var(--dhr-funnel-spring);
  }
  .dhr-funnel-toast.is-on { opacity: 1; scale: 1; translate: -50% -4px; }
}

@container dhr-funnel (width < 1000px) {
  .dhr-funnel {
    .dhr-funnel-app { grid-template-columns: minmax(0, 1fr) 210px; }
    .dhr-funnel-spbody { grid-template-columns: minmax(0, 1fr); }
    .dhr-funnel-bysrc { display: none; }
    .dhr-funnel-kpis > div { padding: 0 10px; }
  }
}
@container dhr-funnel (width < 860px) {
  .dhr-funnel {
    .dhr-funnel-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "head" "filters" "main"; }
    .dhr-funnel-ftoggle { display: inline-flex; }
    .dhr-funnel-filters { display: none; flex-direction: row; flex-wrap: wrap; gap: 14px 20px; padding: 12px 16px; border-left: 0; border-top: 1px solid var(--dhr-funnel-line); border-bottom: 1px solid var(--dhr-funnel-line); }
    &[data-filters="open"] .dhr-funnel-filters { display: flex; }
    .dhr-funnel-fams { display: flex; flex-wrap: wrap; gap: 4px; }
    .dhr-funnel-fams button { grid-template-columns: 14px auto auto; }
    .dhr-funnel-plan { display: none; }
    .dhr-funnel-reset { margin-top: 0; align-self: end; }
    .dhr-funnel-main { grid-template-rows: auto 250px auto; }
    .dhr-funnel-lower { grid-template-columns: minmax(0, 1fr); }
    .dhr-funnel-stage { height: 240px; }
    .dhr-funnel-tth { height: 250px; }
    .dhr-funnel-bysrc { display: block; }
    .dhr-funnel-spbody { grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr); }
  }
}
@container dhr-funnel (width < 600px) {
  .dhr-funnel {
    .dhr-funnel-head { flex-direction: column; align-items: stretch; padding: 14px 14px 10px; }
    .dhr-funnel-headctl { justify-content: space-between; }
    .dhr-funnel-qs button { padding: 6px 9px; }
