  if (kind === 'r') ftip.innerHTML = '<b>' + STAGES[k] + ' → ' + STAGES[k + 1] + '</b>' + NF.format(M.n[k + 1]) + ' of ' + NF.format(M.n[k]) + ' <span>(' + pc(M.n[k + 1], M.n[k]) + ')</span>';
  else if (kind === 'd') ftip.innerHTML = '<b>Left at ' + STAGES[k] + '</b>' + NF.format(M.n[k] - M.n[k + 1]) + (k === 4 ? ' offers declined' : ' · ' + (M.n[k] - M.n[k + 1] - M.w[k]) + ' rejected, ' + M.w[k] + ' withdrew');
  else ftip.innerHTML = '<b>' + STAGES[k] + '</b>' + NF.format(M.n[k]) + ' candidates' + (k ? ' <span>(' + pc(M.n[k], M.n[0]) + ' of applicants)</span>' : '');
  const r = flowEl.getBoundingClientRect();
  placeTip(ftip, flowEl, e.clientX - r.left, e.clientY - r.top);
});
flowEl.addEventListener('pointerleave', () => { ftip.hidden = true; });

/* ================= stage panel ================= */
const stageMedian = (k) => [2, 4, 7, 9, 5, 0][k];
function paintStage() {
  const k = S.stage, A = agg();
  tabs.forEach((t, i) => { t.setAttribute('aria-selected', i === k); t.tabIndex = i === k ? 0 : -1; });
  $('.dhr-funnel-stage').setAttribute('aria-labelledby', tabs[k].id);
  $('[data-k="sp-title"]').textContent = STAGES[k] + (k < 5 ? ' → ' + STAGES[k + 1] : '');
  $('[data-k="sp-note"]').textContent = NF.format(A.n[k]) + (k === 0 ? ' applied' : ' reached · ' + pc(A.n[k], A.n[k - 1]) + ' of ' + STAGES[k - 1].toLowerCase()) + (k && k < 5 ? ' · median ' + stageMedian(k) + ' days here' : '');
  const from = k === 5 ? 4 : k, to = from + 1;
  $('[data-k="sp-conv"]').innerHTML = k === 5 ? 'Offer acceptance by source' : 'Advance to <b>' + STAGES[to].toLowerCase() + '</b>, by source';
  const rows = SRC.map((s) => { const a = agg(qsel(), fsel, (x) => x === s.id); return { s, a: a.n[from], b: a.n[to] }; });
  const max = Math.max(0.01, ...rows.map((r) => (r.a ? r.b / r.a : 0)));
  $('[data-k="sp-src"]').innerHTML = rows.map((r, i) => '<li style="--i:' + i + '" class="' + (S.src.has(r.s.id) ? '' : 'is-off') + '"><span>' + r.s.name + '</span><i style="--c: var(--dhr-funnel-s-' + r.s.id + '); --v:' + (r.a ? r.b / r.a / max : 0) + '"></i><b>' + pc(r.b, r.a) + '</b></li>').join('');
  const now = $('[data-k="sp-now"]');
  if (k === 5) {
    const hs = hiresSel().sort((a, b) => b.q - a.q || a.days - b.days).slice(0, 8);
    $('[data-k="sp-nowh"]').innerHTML = 'Latest signed offers';
    now.innerHTML = hs.length ? hs.map((h, i) => person(h, i, h.days + 'd', false, SRCBY[h.s].name + ' · ' + QS[h.q])).join('') : '<li class="dhr-funnel-empty">No hires match these filters.</li>';
  } else {
    const ppl = NOWP.filter((p) => p.k === k && fsel(p.f) && S.src.has(p.s)).sort((a, b) => b.days - a.days);
    const late = ppl.filter((p) => p.days > SLA[k]).length;
    $('[data-k="sp-nowh"]').innerHTML = '<b>' + ppl.length + '</b> in ' + STAGES[k].toLowerCase() + ' today · <b>' + late + '</b> past the ' + SLA[k] + '\u2011day mark';
    now.innerHTML = ppl.length ? ppl.slice(0, 12).map((p, i) => person(p, i, p.days + 'd', true, SRCBY[p.s].name, p.days > SLA[k])).join('') : '<li class="dhr-funnel-empty">Nobody is waiting in this stage.</li>';
  }
}
function person(p, i, days, nudge, src, late) {
  const ini = p.name.split(' ').map((x) => x[0]).join(''), done = S.nudged.has(p.id);
  return '<li style="--i:' + i + '"><span class="dhr-funnel-av" style="--c: var(--dhr-funnel-s-' + p.s + ')" title="' + src + '" aria-hidden="true">' + ini + '</span><p><b>' + esc(p.name) + '</b><small>' + esc(p.role) + '</small></p>' +
    '<em class="dhr-funnel-days"' + (late ? ' data-late' : '') + ' title="' + (nudge ? 'Days in this stage' : 'Days to hire') + ' · ' + src + '">' + days + '</em>' +
    (nudge ? '<button type="button" class="dhr-funnel-nudge" data-nudge="' + p.id + '"' + (done ? ' aria-disabled="true" title="Reminder already sent to the hiring team today">Nudged' : ' title="Remind the hiring team about ' + esc(p.name) + '">Nudge') + '</button>' : '') + '</li>';
}

/* ================= time to hire: a beeswarm per row ================= */
const sw = { el: $('.dhr-funnel-swarm'), svg: $('.dhr-funnel-swarm .dhr-funnel-svg'), tip: $('.dhr-funnel-swarm .dhr-funnel-tip'), w: 0, h: 0, dots: [], focus: -1 };
const SWP = { l: 106, r: 14, t: 18, b: 22 };
function paintSwarm() {
  if (!sw.w) return;
  const hs = hiresSel(), byFam = S.fam === 'all';
  const rows = byFam ? FAM.map((f) => ({ key: f.id, name: f.name, list: hs.filter((h) => h.f === f.id) }))
    : SRC.filter((s) => S.src.has(s.id)).map((s) => ({ key: s.id, name: s.name, list: hs.filter((h) => h.s === s.id) }));
  const maxD = Math.max(80, Math.ceil(Math.max(0, ...hs.map((h) => h.days)) / 10) * 10);
  const iw = sw.w - SWP.l - SWP.r, ih = sw.h - SWP.t - SWP.b, rh = ih / Math.max(1, rows.length), x = (d) => SWP.l + (d / maxD) * iw, r = Math.max(2.4, Math.min(4, rh / 9));
  const s = sw.svg;
  s.replaceChildren();
  const ax = svg('g', null, s);
  for (let d = 0; d <= maxD; d += maxD > 100 ? 20 : 10) {
    svg('line', { x1: x(d), x2: x(d), y1: SWP.t - 6, y2: SWP.t + ih, style: 'stroke: var(--dhr-funnel-line)' }, ax);
    const t = svg('text', { x: x(d), y: sw.h - 6, 'text-anchor': 'middle' }, ax); t.textContent = d === 0 ? '0 d' : d;
  }
  const tg = svg('g', { class: 'dhr-funnel-target' }, s);
  svg('line', { x1: x(45), x2: x(45), y1: SWP.t - 10, y2: SWP.t + ih }, tg);
  const tt = svg('text', { x: x(45) + 4, y: SWP.t - 4 }, tg); tt.textContent = 'target 45';
  sw.dots = [];
  let i = 0;
  rows.forEach((row, ri) => {
    const g = svg('g', { class: 'dhr-funnel-row' }, s), cy = SWP.t + rh * (ri + 0.5);
    if (ri) svg('line', { x1: 0, x2: sw.w - SWP.r, y1: SWP.t + rh * ri, y2: SWP.t + rh * ri }, g);
    const nm = svg('text', { x: 0, y: cy - 2, class: 'is-name' }, g); nm.textContent = row.name;
    const md = median(row.list.map((h) => h.days));
    const sub = svg('text', { x: 0, y: cy + 11 }, g); sub.textContent = row.list.length ? row.list.length + ' · median ' + Math.round(md) + 'd' : 'no hires';
    /* dodge: each dot takes the nearest free vertical slot */
    const placed = [];
    row.list.slice().sort((a, b) => a.days - b.days || a.id - b.id).forEach((h) => {
      const px = x(h.days);
      let off = 0;
      for (let tries = 0; tries < 40; tries++) {
        off = (tries % 2 ? 1 : -1) * Math.ceil(tries / 2) * r * 1.9;
        if (Math.abs(off) > rh / 2 - r) { off = (((h.id * 37) % 100) / 100 - 0.5) * (rh - 2 * r); break; }
        if (!placed.some((p) => Math.hypot(p.x - px, p.y - (cy + off)) < r * 2.05)) break;
      }
      const d = { h, x: px, y: cy + off };
      placed.push(d); sw.dots.push(d);
      svg('circle', { class: 'dhr-funnel-dotc', cx: px, cy: cy + off, r, style: 'fill: var(--dhr-funnel-s-' + h.s + '); --i:' + (i++) }, g);
    });
    if (row.list.length) {
      svg('line', { class: 'dhr-funnel-med', x1: x(md), x2: x(md), y1: cy - rh * 0.34, y2: cy + rh * 0.34 }, g);
    }
  });
  sw.ring = svg('circle', { class: 'dhr-funnel-ring', r: r + 3, opacity: 0 }, s);
  $('[data-k="tth-note"]').textContent = hs.length + ' hires by ' + (byFam ? 'role family' : 'source');
  sw.order = sw.dots.slice();
  requestAnimationFrame(() => { if (!root.isConnected) return; setTimeout(() => sw.svg.classList.add('is-ready'), 900); });
}
function swarmTip(d) {
  if (!d) { sw.tip.hidden = true; if (sw.ring) sw.ring.setAttribute('opacity', 0); return; }
  sw.ring.setAttribute('cx', d.x); sw.ring.setAttribute('cy', d.y); sw.ring.setAttribute('opacity', 1);
  sw.tip.innerHTML = '<b>' + esc(d.h.role) + '</b>' + esc(d.h.name) + ' · ' + SRCBY[d.h.s].name + '<br><span>' + d.h.days + ' days · signed ' + QS[d.h.q] + '</span>';
  placeTip(sw.tip, sw.el, d.x, d.y);
}
sw.el.addEventListener('pointermove', (e) => {
  const r = sw.el.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top;
  let best = null, bd = 14;
  for (const d of sw.dots) { const dd = Math.hypot(d.x - px, d.y - py); if (dd < bd) { bd = dd; best = d; } }
  swarmTip(best);
});
sw.el.addEventListener('pointerleave', () => swarmTip(null));
sw.el.addEventListener('blur', () => swarmTip(null));
sw.el.addEventListener('keydown', (e) => {
  const st = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
  if (e.key === 'Escape') { swarmTip(null); return; }
  if (!st || !sw.order.length) return;
  e.preventDefault();
  sw.focus = Math.max(0, Math.min(sw.order.length - 1, sw.focus + st));
  swarmTip(sw.order[sw.focus]);
});
new ResizeObserver(() => {
  sw.w = sw.el.clientWidth; sw.h = sw.el.clientHeight;
  sw.svg.setAttribute('viewBox', '0 0 ' + sw.w + ' ' + sw.h);
  paintSwarm();
}).observe(sw.el);

/* ================= filters ================= */
function paintFilters() {
  const qs = qsel();
  $('.dhr-funnel-fams').innerHTML = [{ id: 'all', name: 'All families' }, ...FAM].map((f) => {
    const a = agg(qs, (x) => f.id === 'all' || x === f.id);
    return '<button type="button" role="radio" data-fam="' + f.id + '" aria-checked="' + (S.fam === f.id) + '" tabindex="' + (S.fam === f.id ? 0 : -1) + '"><span>' + f.name + '</span><em>' + NF.format(a.n[0]) + '</em></button>';
  }).join('');
  $('.dhr-funnel-srcs').innerHTML = SRC.map((s) => {
    const on = S.src.has(s.id), last = on && S.src.size === 1;
    return '<button type="button" data-src="' + s.id + '" aria-pressed="' + on + '" style="--c: var(--dhr-funnel-s-' + s.id + ')"' + (last ? ' aria-disabled="true" title="At least one source stays selected"' : ' title="' + (on ? 'Hide ' : 'Show ') + s.name + '"') + '><i aria-hidden="true"></i>' + s.name + '</button>';
  }).join('');
  const all = agg(qs, () => true, () => true), plan = qs.reduce((t, q) => t + FAM.reduce((u, f) => u + f.plan[q], 0), 0);
  $('[data-k="plan"]').innerHTML = '<b>' + all.n[5] + '</b>of ' + plan + ' planned hires';
  $('[data-k="planbars"]').innerHTML = FAM.map((f) => {
    const got = agg(qs, (x) => x === f.id, () => true).n[5], p = qs.reduce((t, q) => t + f.plan[q], 0);
    return '<li class="' + (fsel(f.id) ? '' : 'is-dim') + '"><span>' + f.name + '</span><i style="--v:' + (got / p) + '"' + (got >= p ? ' data-over' : '') + '></i><b>' + got + '/' + p + '</b></li>';
  }).join('');
  const dirty = S.q !== DEF.q || S.fam !== DEF.fam || S.src.size !== SRC.length;
  const rb = $('[data-act="reset"]');
  rb.setAttribute('aria-disabled', !dirty); rb.title = dirty ? 'Back to Q3, every family and source' : 'Filters are already at their defaults';
  const n = (S.fam !== 'all' ? 1 : 0) + (SRC.length - S.src.size);
  const fc = $('[data-k="fcount"]'); fc.hidden = !n; fc.textContent = n;
}

/* ================= render ================= */
function render() {
  $('[data-k="qlabel"]').textContent = S.q === 'all' ? 'Oct 2025 – Sep 2026' : QL[+S.q];
  for (const b of $$('.dhr-funnel-qs [role=radio]')) { const on = b.dataset.q === S.q; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }
  thumb();
  paintFilters(); paintKpis(); updateFlow(); paintStage(); paintSwarm();
}

root.addEventListener('click', (e) => {
  const t = e.target.closest('button');
  if (!t || !root.contains(t) || t.getAttribute('aria-disabled') === 'true') return;
  if (t.dataset.q) { if (t.dataset.q === S.q) return; S.q = t.dataset.q; return render(); }
  if (t.dataset.stage) { S.stage = +t.dataset.stage; paintStage(); if (F.shown) drawFlow(F.shown); return; }
  if (t.dataset.fam) { if (S.fam === t.dataset.fam) return; S.fam = t.dataset.fam; render(); $('[data-fam="' + S.fam + '"]').focus({ preventScroll: true }); return; }
  if (t.dataset.src) { const k = t.dataset.src; if (S.src.has(k)) S.src.delete(k); else S.src.add(k); render(); const b = $('[data-src="' + k + '"]'); if (b) b.focus({ preventScroll: true }); return; }
  if (t.dataset.act === 'reset') { S.q = DEF.q; S.fam = DEF.fam; S.src = new Set(DEF.src); render(); return toast('Filters reset to Q3, all families and sources'); }
  if (t.dataset.nudge) {
    const p = NOWP[+t.dataset.nudge];
    S.nudged.add(p.id);
    t.textContent = 'Nudged'; t.setAttribute('aria-disabled', 'true'); t.title = 'Reminder already sent to the hiring team today';
    return toast('Reminder sent about ' + p.name + ' · ' + p.days + ' days in ' + STAGES[p.k].toLowerCase());
  }
  if (t.classList.contains('dhr-funnel-ftoggle')) {
    const open = root.dataset.filters !== 'open';
    if (open) root.dataset.filters = 'open'; else delete root.dataset.filters;
    t.setAttribute('aria-expanded', open);
  }
});
root.addEventListener('keydown', (e) => {
  const tab = e.target.closest('[role=tab]');
  if (tab) {
    const i = tabs.indexOf(tab), to = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: 5 }[e.key];
    if (to === undefined) return;
    e.preventDefault();
    const n = tabs[(to + 6) % 6]; n.focus(); n.click(); return;
  }
  if (e.target.getAttribute('role') === 'radio') {
    const st = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key];
    if (!st) return;
    e.preventDefault();
    const items = $$('[role=radio]', e.target.parentElement), n = items[(items.indexOf(e.target) + st + items.length) % items.length];
    n.focus(); n.click();
  }
  if (e.key === 'Escape' && root.dataset.filters === 'open') { delete root.dataset.filters; const b = $('.dhr-funnel-ftoggle'); b.setAttribute('aria-expanded', 'false'); b.focus(); }
});

let started = false;
function intro() { if (started || !root.isConnected) return; started = true; render(); }
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((es) => { if (es.some((x) => x.isIntersecting)) { io.disconnect(); intro(); } });
  io.observe(root);
} else intro();
new ResizeObserver(thumb).observe(root);

