/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-survey {
  width: 100%;
  height: var(--dhr-survey-h, 680px);
  container-type: inline-size;
  container-name: dhr-survey;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-survey-bg);
  color: var(--dhr-survey-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-survey-accent);
  scrollbar-color: var(--dhr-survey-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-survey-focus, var(--dhr-survey-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@property --dhr-survey-p { syntax: "<number>"; inherits: false; initial-value: 0; }
@keyframes dhr-survey-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-survey-grow { from { scale: 0 1; } }
@keyframes dhr-survey-rise { from { scale: 1 0; } }

.dhr-survey {
  /* re-theme: paper, ink, agree and disagree */
  --dhr-survey-bg: oklch(0.974 0.011 88);
  --dhr-survey-ink: oklch(0.27 0.016 60);
  --dhr-survey-pos: oklch(0.56 0.095 182);
  --dhr-survey-neg: oklch(0.6 0.15 33);
  --dhr-survey-accent: var(--dhr-survey-pos);

  --dhr-survey-sa: color-mix(in oklch, var(--dhr-survey-pos), var(--dhr-survey-ink) 22%);
  --dhr-survey-a: color-mix(in oklch, var(--dhr-survey-pos) 62%, var(--dhr-survey-bg));
  --dhr-survey-n: color-mix(in oklch, var(--dhr-survey-ink) 13%, var(--dhr-survey-bg));
  --dhr-survey-d: color-mix(in oklch, var(--dhr-survey-neg) 60%, var(--dhr-survey-bg));
  --dhr-survey-sd: color-mix(in oklch, var(--dhr-survey-neg), var(--dhr-survey-ink) 18%);
  --dhr-survey-card: color-mix(in oklch, var(--dhr-survey-bg), white 65%);
  --dhr-survey-sunk: color-mix(in oklch, var(--dhr-survey-bg), var(--dhr-survey-ink) 4.5%);
  --dhr-survey-line: color-mix(in oklch, var(--dhr-survey-ink) 10%, transparent);
  --dhr-survey-line2: color-mix(in oklch, var(--dhr-survey-ink) 20%, transparent);
  --dhr-survey-muted: color-mix(in oklch, var(--dhr-survey-ink) 60%, var(--dhr-survey-bg));
  --dhr-survey-faint: color-mix(in oklch, var(--dhr-survey-ink) 38%, var(--dhr-survey-bg));
  --dhr-survey-ease: cubic-bezier(0.2, 0.75, 0.15, 1);
  --dhr-survey-spring: linear(0, 0.011, 0.044 2.3%, 0.17 4.9%, 0.74 13.4%, 0.95 17.6%, 1.04 21%, 1.07 24.5%, 1.064 28%, 1.03 34%, 1.002 44%, 0.996 54%, 1);
  --dhr-survey-mono: ui-monospace, Menlo, Consolas, monospace;
  color-scheme: light;
}

.dhr-survey {
  .dhr-survey-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhr-survey-muted); }
  .dhr-survey-app {
    display: grid; height: 100%;
    grid-template-columns: 212px minmax(0, 1fr) 286px;
    grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-areas: "side head head" "side tools tools" "side main detail";
  }

  /* ---------- teams ---------- */
  .dhr-survey-side { grid-area: side; min-height: 0; overflow: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 10px; padding: 18px 12px 14px; border-right: 1px solid var(--dhr-survey-line); background: var(--dhr-survey-sunk); }
  .dhr-survey-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 10px; }
  .dhr-survey-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 50%; background: var(--dhr-survey-pos); fill: none; stroke: white; stroke-width: 1.8; stroke-linecap: round; }
  .dhr-survey-brand span { display: grid; line-height: 1.25; min-width: 0; }
  .dhr-survey-brand b { font-size: 14px; font-weight: 700; letter-spacing: -0.01em; }
  .dhr-survey-brand small { font-size: 11px; color: var(--dhr-survey-muted); }
  .dhr-survey-side > .dhr-survey-eyebrow { padding: 0 6px; }
  .dhr-survey-teams { display: grid; gap: 1px; }
  .dhr-survey-teams button {
    display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 6px 8px; border-radius: 9px;
    font-size: 12.5px; font-weight: 560; color: var(--dhr-survey-muted); transition: background-color 150ms, color 150ms;
  }
  .dhr-survey-teams button:hover { background: color-mix(in oklch, var(--dhr-survey-ink) 5%, transparent); color: var(--dhr-survey-ink); }
  .dhr-survey-teams [aria-checked="true"] { background: var(--dhr-survey-card); color: var(--dhr-survey-ink); box-shadow: 0 0 0 1px var(--dhr-survey-line), 0 1px 2px color-mix(in oklch, var(--dhr-survey-ink) 6%, transparent); }
  .dhr-survey-teams span:nth-child(2) { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-survey-teams em { font: 500 10.5px var(--dhr-survey-mono); font-style: normal; font-variant-numeric: tabular-nums; }
  .dhr-survey-ring {
