/* nice axis: the tightest 0..max scale in 1/2/2.5/5 steps with 3 to 6 intervals */
function nice(top) {
  let best = null;
  for (const n of [3, 4, 5, 6]) { const t = ticks(top, n); if (!best || t.at(-1) < best.at(-1)) best = t; }
  return best;
}
/* axis ticks: 0..max in 1/2/2.5/5 steps */
function ticks(max, count = 4) {
  const raw = max / count, mag = Math.pow(10, Math.floor(Math.log10(raw || 1)));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => s >= raw) || mag * 10;
  const out = [];
  for (let v = 0; v <= max + step * 0.001; v += step) out.push(+v.toFixed(6));
  if (out[out.length - 1] < max) out.push(+(out[out.length - 1] + step).toFixed(6));
