  let l = x + 14; if (l + tw > bw - 4) l = x - tw - 14;
  let t = y - th - 12; if (t < 4) t = Math.min(bh - th - 4, y + 16);
  tip.style.translate = Math.max(4, l) + 'px ' + Math.max(4, t) + 'px';
}

/* FLIP: measure, mutate, then play each keyed node back from where it was */
function flip(nodes, mutate, ms = 460) {
  const before = new Map(nodes().map((n) => [n, n.getBoundingClientRect()]));
  mutate();
  if (RM) return;
  for (const n of nodes()) {
    const a = before.get(n);
    if (!a) continue;
    const b = n.getBoundingClientRect();
    const dx = a.left - b.left, dy = a.top - b.top;
    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) continue;
    n.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }],
      { duration: ms, easing: 'cubic-bezier(.2,.75,.15,1)' });
  }
}

