/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-labour {
  width: 100%;
  height: var(--dhr-labour-h, 680px);
  container-type: inline-size;
  container-name: dhr-labour;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-labour-bg);
  color: var(--dhr-labour-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-labour-accent);
  scrollbar-color: var(--dhr-labour-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-labour-focus, var(--dhr-labour-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@keyframes dhr-labour-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-labour-tile { from { opacity: 0; scale: 0.6; } }
@keyframes dhr-labour-rise { from { scale: 1 0; } }

.dhr-labour {
  /* re-theme: ground, ink, highlight, and the two ends of the budget scale */
  --dhr-labour-bg: oklch(0.205 0.005 85);
  --dhr-labour-ink: oklch(0.94 0.008 85);
  --dhr-labour-accent: oklch(0.84 0.12 86);
  --dhr-labour-under: oklch(0.7 0.09 205);
  --dhr-labour-over: oklch(0.72 0.15 48);
  --dhr-labour-mfg: oklch(0.66 0.085 62);
  --dhr-labour-ret: oklch(0.67 0.09 150);
  --dhr-labour-ecom: oklch(0.65 0.08 245);
  --dhr-labour-dsn: oklch(0.66 0.1 335);
  --dhr-labour-log: oklch(0.73 0.1 100);
  --dhr-labour-corp: oklch(0.66 0.025 85);
  --dhr-labour-c-base: oklch(0.86 0.03 85);
  --dhr-labour-c-ot: oklch(0.76 0.13 70);
