    let c = 1 + gauss() * 0.052 - (sex === 'W' ? 0.026 : 0) + (hire >= 2024 ? 0.03 : 0) - (2026 - hire) * 0.0016;
    c = Math.max(0.81, Math.min(1.19, c));
    const sal = Math.round(L.mid * c * 2) / 2;
