/* ================= lanes + dots ================= */
const lanesEl = $('.dhr-equity-lanes');
lanesEl.innerHTML = LEVELS.map((L, li) => '<div class="dhr-equity-lane" style="--i:' + li + '" role="group" aria-label="' + L.id + ' ' + esc(L.title) + '">' +
  '<div class="dhr-equity-lv"><b>' + L.id + '</b><small>' + esc(L.title) + '</small></div><div class="dhr-equity-plot" data-li="' + li + '"><span class="dhr-equity-med" data-m="a"></span><span class="dhr-equity-med" data-m="b"></span></div><div class="dhr-equity-ls"><b></b><small></small></div></div>').join('');
