$('.dhr-equity-axis').innerHTML = '<span>Level</span><div class="dhr-equity-ticks">' + [0.8, 0.85, 0.9, 0.95, 1, 1.05, 1.1, 1.15, 1.2].map((v) => '<span class="' + ([0.85, 1, 1.15].includes(v) ? 'is-key' : '') + '" style="--x:' + xs(v).toFixed(4) + '">' + (v === 0.85 ? 'min' : v === 1 ? 'mid' : v === 1.15 ? 'max' : v.toFixed(2)) + '</span>').join('') + '</div><span>Gap</span>';
/* vertical dodge so overlapping people stay visible: each dot takes the nearest free slot;
