function place(people, r, lim) {
  const placed = [];
  let missed = 0;
  for (const { e, x } of people) {
    let y = null;
    for (let k = 0; k < 40; k++) {
      const t = (k % 2 ? 1 : -1) * Math.ceil(k / 2) * r * 1.25;
      if (Math.abs(t) > lim) break;
