  const lanes = plots.map((p, li) => ({
    lim: Math.max(0, p.clientHeight / 2 - 7),
    people: EMP.filter((e) => e.li === li).map((e) => ({ e, x: xs(compa(e)) * W })).sort((a, b) => a.x - b.x || (a.e.id < b.e.id ? -1 : 1))
