  tip.innerHTML = '<b>' + p.id + ' · ' + LENS[S.lens][grp(p)] + '</b>' + LEVELS[p.li].id + ' · ' + usd(salOf(p)) + ' · ' + c.toFixed(2) + ' of mid';
