/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-absence {
  width: 100%;
  height: var(--dhr-absence-h, 680px);
  container-type: inline-size;
  container-name: dhr-absence;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-absence-bg);
  color: var(--dhr-absence-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-absence-accent);
  scrollbar-color: var(--dhr-absence-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-absence-focus, var(--dhr-absence-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@keyframes dhr-absence-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-absence-cell { from { opacity: 0; scale: 0.4; } }
@keyframes dhr-absence-up { from { scale: 1 0; } }
@keyframes dhr-absence-row { from { opacity: 0.2; translate: 0 8px; } }

.dhr-absence {
  /* re-theme: ground, ink, the heat colour and the overtime colour */
  --dhr-absence-bg: oklch(0.2 0.012 58);
  --dhr-absence-ink: oklch(0.94 0.014 80);
  --dhr-absence-hot: oklch(0.8 0.15 70);
  --dhr-absence-ot: oklch(0.76 0.1 192);
  --dhr-absence-accent: var(--dhr-absence-hot);
  --dhr-absence-r-sick: oklch(0.8 0.14 78);
  --dhr-absence-r-lts: oklch(0.64 0.13 40);
  --dhr-absence-r-fam: oklch(0.75 0.1 150);
  --dhr-absence-r-inj: oklch(0.72 0.12 300);
  --dhr-absence-r-un: oklch(0.67 0.17 25);

  --dhr-absence-card: color-mix(in oklch, var(--dhr-absence-bg), var(--dhr-absence-ink) 4.5%);
  --dhr-absence-raise: color-mix(in oklch, var(--dhr-absence-bg), var(--dhr-absence-ink) 9%);
  --dhr-absence-sunk: color-mix(in oklch, var(--dhr-absence-bg), black 24%);
  --dhr-absence-cell0: color-mix(in oklch, var(--dhr-absence-bg), var(--dhr-absence-ink) 7%);
  --dhr-absence-line: color-mix(in oklch, var(--dhr-absence-ink) 9%, transparent);
  --dhr-absence-line2: color-mix(in oklch, var(--dhr-absence-ink) 17%, transparent);
  --dhr-absence-muted: color-mix(in oklch, var(--dhr-absence-ink) 60%, var(--dhr-absence-bg));
  --dhr-absence-faint: color-mix(in oklch, var(--dhr-absence-ink) 36%, var(--dhr-absence-bg));
  --dhr-absence-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dhr-absence-spring: linear(0, 0.01, 0.04 2.2%, 0.16 4.8%, 0.74 13.4%, 0.95 17.4%, 1.03 20.4%, 1.065 23.8%, 1.07 27%, 1.045 32%, 1.008 42%, 0.996 50%, 1);
