  .dhr-absence-grid { grid-column: 2; grid-row: 2; display: grid; grid-template-rows: repeat(7, 1fr); gap: 2px; aspect-ratio: var(--n) / 7; }
  .dhr-absence-c {
    border-radius: 2px; background: color-mix(in oklch, var(--dhr-absence-hot) calc(var(--v, 0) * 100%), var(--dhr-absence-cell0));
