  .dhr-absence-stack { width: 100%; max-width: 30px; height: calc(var(--h) * 100%); display: flex; flex-direction: column-reverse; border-radius: 3px 3px 1px 1px; overflow: hidden; transform-origin: bottom; animation: dhr-absence-up 520ms var(--dhr-absence-spring) calc(var(--i) * 35ms) both; transition: height 450ms var(--dhr-absence-ease); }
