  .dhr-absence-stack .dhr-absence-gh { background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dhr-absence-ink) 22%, transparent) 0 2px, transparent 2px 5px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dhr-absence-ink) 16%, transparent); border-radius: inherit; }
  .dhr-absence-dowbars li { height: 100%; display: grid; grid-template-rows: auto 1fr auto; align-items: end; justify-items: center; gap: 3px; font-variant-numeric: tabular-nums; }
  .dhr-absence-dowbars b { font: 600 10.5px var(--dhr-absence-mono); }
  .dhr-absence-dowbars i { width: 100%; max-width: 46px; height: calc(var(--v) * 100%); border-radius: 4px 4px 1px 1px; background: color-mix(in oklch, var(--dhr-absence-hot) calc(35% + var(--v) * 65%), var(--dhr-absence-cell0)); transform-origin: bottom; animation: dhr-absence-up 520ms var(--dhr-absence-spring) calc(var(--i) * 40ms) both; transition: height 450ms var(--dhr-absence-ease); }
  .dhr-absence-dowbars span { font-size: 10.5px; color: var(--dhr-absence-muted); }
