  .dhr-absence-day h3 { font-size: 16px; font-weight: 700; letter-spacing: -0.015em; line-height: 1.25; animation: dhr-absence-in 300ms var(--dhr-absence-ease) both; }
  .dhr-absence-mixbar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; background: var(--dhr-absence-line); }
