  .dhr-absence-who button { width: 100%; display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 6px 4px; border-radius: 7px; transition: background-color 140ms; animation: dhr-absence-in 300ms var(--dhr-absence-ease) calc(var(--i) * 25ms) both; }
  .dhr-absence-who button:hover { background: color-mix(in oklch, var(--dhr-absence-ink) 6%, transparent); }
