  .dhr-absence-key .is-ot { height: 0; border-top: 2.5px solid var(--dhr-absence-ot); border-radius: 0; }
  .dhr-absence-plot { position: relative; flex: 1; min-height: 190px; cursor: crosshair; border-radius: 8px; }
  .dhr-absence-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  .dhr-absence-corr { margin-top: 6px; font-size: 12px; color: var(--dhr-absence-muted); }
  .dhr-absence-corr b { color: var(--dhr-absence-ink); font-variant-numeric: tabular-nums; }
  .dhr-absence-tip {
    position: absolute; left: 0; top: 0; z-index: 8; min-width: 170px; padding: 8px 11px; border-radius: 10px; pointer-events: none; font-size: 11.5px; line-height: 1.45;
    background: var(--dhr-absence-raise); color: var(--dhr-absence-ink); box-shadow: 0 0 0 1px var(--dhr-absence-line2), 0 16px 30px -12px oklch(0 0 0 / 0.75); transition: translate 100ms var(--dhr-absence-ease);
  }
  .dhr-absence-tip b { display: block; font-size: 12px; margin-bottom: 2px; }
  .dhr-absence-tip span { color: var(--dhr-absence-muted); }
  .dhr-absence-sites { padding: 4px 10px 6px; overflow-x: auto; }
  .dhr-absence-table { width: 100%; font-size: 12px; font-variant-numeric: tabular-nums; }
  .dhr-absence-table th { padding: 8px 8px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.07em; text-transform: uppercase; color: var(--dhr-absence-muted); text-align: right; border-bottom: 1px solid var(--dhr-absence-line2); white-space: nowrap; }
  .dhr-absence-table th:first-child, .dhr-absence-table td:first-child { text-align: left; }
  .dhr-absence-table td { padding: 7px 8px; text-align: right; border-bottom: 1px solid var(--dhr-absence-line); white-space: nowrap; }
  .dhr-absence-table tr.is-total td { font-weight: 700; border-bottom: 0; }
  .dhr-absence-table tr.is-dim td { opacity: 0.42; }

  /* ---------- Bradford ---------- */
  .dhr-absence-brad { display: grid; gap: 10px; height: 100%; min-height: 420px; grid-template-rows: auto minmax(0, 1fr); }
  .dhr-absence-bradbar { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
  .dhr-absence-bnote { font-size: 12px; color: var(--dhr-absence-muted); }
  .dhr-absence-bnote b { color: var(--dhr-absence-ink); }
  .dhr-absence-tablewrap { min-height: 0; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dhr-absence-card); box-shadow: inset 0 0 0 1px var(--dhr-absence-line); }
  .dhr-absence-btable th { position: sticky; top: 0; z-index: 1; background: var(--dhr-absence-card); }
  .dhr-absence-btable th button { display: inline-flex; gap: 3px; border-radius: 4px; }
  .dhr-absence-btable th button:hover { color: var(--dhr-absence-ink); }
  [aria-sort="ascending"] > button::after { content: "\2191"; color: var(--dhr-absence-ink); }
  [aria-sort="descending"] > button::after { content: "\2193"; color: var(--dhr-absence-ink); }
  .dhr-absence-btable tbody tr { cursor: pointer; transition: background-color 130ms; }
  .dhr-absence-btable tbody tr:hover { background: color-mix(in oklch, var(--dhr-absence-ink) 4.5%, transparent); }
  .dhr-absence-btable tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dhr-absence-hot) 12%, transparent); }
  .dhr-absence-btable tbody tr:focus-visible { outline-offset: -2px; }
  @supports (animation-timeline: view()) {
    .dhr-absence-btable tbody tr { animation: dhr-absence-row linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
  }
  .dhr-absence-pn { display: grid; line-height: 1.25; }
  .dhr-absence-pn b { font-weight: 620; }
  .dhr-absence-pn small { font-size: 11px; color: var(--dhr-absence-muted); }
  .dhr-absence-bscore { display: inline-flex; align-items: center; justify-content: flex-end; gap: 8px; }
  .dhr-absence-bscore i { width: 64px; height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--tc, var(--dhr-absence-faint)) calc(var(--v) * 100%), var(--dhr-absence-line) 0); }
  .dhr-absence-trig { display: inline-block; min-width: 62px; padding: 1px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 700; text-align: center; background: var(--dhr-absence-line); color: var(--dhr-absence-muted); }
  .dhr-absence-trig[data-t="1"] { background: color-mix(in oklch, var(--dhr-absence-hot) 20%, transparent); color: var(--dhr-absence-hot); }
  .dhr-absence-trig[data-t="2"] { background: color-mix(in oklch, var(--dhr-absence-r-lts) 30%, transparent); color: color-mix(in oklch, var(--dhr-absence-r-lts), white 30%); }
  .dhr-absence-trig[data-t="3"] { background: color-mix(in oklch, var(--dhr-absence-r-un) 30%, transparent); color: color-mix(in oklch, var(--dhr-absence-r-un), white 30%); }
  .dhr-absence-mini { position: relative; display: block; width: 100%; min-width: 150px; height: 12px; border-radius: 3px; background: var(--dhr-absence-sunk); }
  .dhr-absence-mini i, .dhr-absence-strip i { position: absolute; top: 0; bottom: 0; left: calc(var(--a) * 100%); width: max(2px, calc(var(--l) * 100%)); border-radius: 1px; background: var(--c); }

  /* ---------- drawer ---------- */
  .dhr-absence-drawer {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 10px; width: min(340px, calc(100% - 20px)); display: flex; flex-direction: column; gap: 12px;
    padding: 16px; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dhr-absence-raise);
    box-shadow: 0 0 0 1px var(--dhr-absence-line2), 0 30px 60px -20px oklch(0 0 0 / 0.8);
    transition: opacity 240ms var(--dhr-absence-ease), translate 480ms var(--dhr-absence-spring);
  }
  @starting-style { .dhr-absence-drawer { opacity: 0; translate: 26px 0; } }
  .dhr-absence-dhead { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
  .dhr-absence-dhead h3 { font-size: 17px; font-weight: 700; letter-spacing: -0.015em; margin-top: 2px; }
  .dhr-absence-dhead h3:focus { outline: none; }
