  .dhr-absence-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dhr-absence-score { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
  .dhr-absence-score div { display: grid; padding: 8px 10px; border-radius: 10px; background: var(--dhr-absence-card); }
  .dhr-absence-score dt, .dhr-absence-score span { font-size: 10.5px; color: var(--dhr-absence-muted); }
  .dhr-absence-score b { font-size: 19px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
  .dhr-absence-strip { position: relative; height: 22px; border-radius: 5px; background: var(--dhr-absence-sunk); box-shadow: inset 0 0 0 1px var(--dhr-absence-line); }
  .dhr-absence-strip::after { content: "52 weeks to 27 Sep"; position: absolute; right: 0; bottom: -15px; font-size: 9.5px; color: var(--dhr-absence-muted); }
  .dhr-absence-spells { display: grid; gap: 1px; margin-top: 8px; font-size: 12px; }
  .dhr-absence-spells li { display: grid; grid-template-columns: 8px 1fr auto; align-items: center; gap: 9px; padding: 5px 0; border-bottom: 1px solid var(--dhr-absence-line); }
  .dhr-absence-spells i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  .dhr-absence-spells em { font: 500 11px var(--dhr-absence-mono); font-style: normal; color: var(--dhr-absence-muted); }
  .dhr-absence-spells li.is-ex { opacity: 0.55; }
  .dhr-absence-dacts { margin-top: auto; padding-top: 6px; }
  .dhr-absence-primary { width: 100%; padding: 9px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 680; text-align: center; background: var(--dhr-absence-hot); color: var(--dhr-absence-bg); transition: background-color 150ms, scale 200ms var(--dhr-absence-spring); }
  .dhr-absence-primary:hover:not([aria-disabled="true"]) { background: color-mix(in oklch, var(--dhr-absence-hot), white 15%); }
  .dhr-absence-primary:active { scale: 0.98; }
  .dhr-absence-primary[aria-disabled="true"] { background: color-mix(in oklch, var(--dhr-absence-r-fam) 22%, transparent); color: var(--dhr-absence-r-fam); }

  .dhr-absence-toast {
    position: absolute; z-index: 30; left: 50%; bottom: 16px; translate: -50% 0; padding: 8px 14px; border-radius: 10px; max-width: calc(100% - 32px);
    background: var(--dhr-absence-ink); color: var(--dhr-absence-bg); font-size: 12px; font-weight: 600; opacity: 0; scale: 0.95; pointer-events: none;
    transition: opacity 200ms, scale 360ms var(--dhr-absence-spring), translate 360ms var(--dhr-absence-spring);
  }
  .dhr-absence-toast.is-on { opacity: 1; scale: 1; translate: -50% -4px; }
