}

/* ================= cover chart (canvas) ================= */
const cv = { plot: $('.dhr-absence-cover .dhr-absence-plot'), c: $('.dhr-absence-canvas'), tip: $('.dhr-absence-cover .dhr-absence-tip'), w: 0, h: 0, prog: 0, hover: -1, intro: false };
cv.ctx = cv.c.getContext('2d');
const CP = { l: 44, r: 12, t: 12, b: 24 };
function coverSeries() {
  const wa = 52 - S.wk, out = [];
  for (let w = wa; w < 52; w++) {
    let lost = 0;
    for (let d = w * 7; d < w * 7 + 7; d++) lost += absOn(d, true).length * 8;
    const ot = SITES.reduce((t, s, k) => t + (siteOk(s.id) ? OT[k][w] : 0), 0);
    out.push({ w, lost, ot });
