  const dpr = Math.min(2, devicePixelRatio || 1);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, w, h);
  const D = coverSeries(), iw = w - CP.l - CP.r, ih = h - CP.t - CP.b;
  const max = nice(Math.max(...D.map((d) => Math.max(d.lost, d.ot))) * 1.05).at(-1);
  const X = (k) => CP.l + (D.length === 1 ? iw / 2 : (k / (D.length - 1)) * iw), Y = (v) => CP.t + ih * (1 - v / max);
  ctx.font = '500 10.5px system-ui, sans-serif'; ctx.textBaseline = 'middle'; ctx.textAlign = 'right';
  for (const v of nice(max)) {
    ctx.globalAlpha = v === 0 ? 0.22 : 0.09; ctx.strokeStyle = ink; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(CP.l, Math.round(Y(v)) + 0.5); ctx.lineTo(w - CP.r, Math.round(Y(v)) + 0.5); ctx.stroke();
    ctx.globalAlpha = 0.55; ctx.fillStyle = ink; ctx.fillText(NF.format(v), CP.l - 8, Y(v));
  }
  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  /* a month label sits under its first week; one crowded by the next (the partial first month) is dropped */
  let pm = -1;
  const ml = [];
  D.forEach((d, k) => { const m = dateOf(d.w * 7).getUTCMonth(); if (m !== pm) { ml.push({ x: X(k), t: dateOf(d.w * 7).toLocaleDateString('en-GB', { month: 'short', timeZone: 'UTC' }) }); pm = m; } });
  ctx.globalAlpha = 0.55;
  ml.forEach((l, j) => { if (!ml[j + 1] || ml[j + 1].x - l.x >= 34) ctx.fillText(l.t, Math.max(CP.l, l.x), h - 6); });
  ctx.save(); ctx.beginPath(); ctx.rect(0, 0, CP.l + iw * cv.prog + 1, h); ctx.clip();
  const grad = ctx.createLinearGradient(0, CP.t, 0, CP.t + ih);
  grad.addColorStop(0, hot); grad.addColorStop(1, 'transparent');
  ctx.globalAlpha = 0.42; ctx.fillStyle = grad;
  ctx.beginPath(); ctx.moveTo(X(0), Y(0)); D.forEach((d, k) => ctx.lineTo(X(k), Y(d.lost))); ctx.lineTo(X(D.length - 1), Y(0)); ctx.closePath(); ctx.fill();
  ctx.globalAlpha = 1; ctx.strokeStyle = hot; ctx.lineWidth = 1.6; ctx.lineJoin = 'round';
  ctx.beginPath(); D.forEach((d, k) => (k ? ctx.lineTo(X(k), Y(d.lost)) : ctx.moveTo(X(k), Y(d.lost)))); ctx.stroke();
  ctx.strokeStyle = ot; ctx.lineWidth = 2.4;
  ctx.beginPath(); D.forEach((d, k) => (k ? ctx.lineTo(X(k), Y(d.ot)) : ctx.moveTo(X(k), Y(d.ot)))); ctx.stroke();
  ctx.restore();
  if (cv.hover >= 0 && cv.hover < D.length) {
    const x = Math.round(X(cv.hover)) + 0.5, d = D[cv.hover];
    ctx.globalAlpha = 0.35; ctx.strokeStyle = ink; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(x, CP.t); ctx.lineTo(x, CP.t + ih); ctx.stroke(); ctx.setLineDash([]);
    ctx.globalAlpha = 1; ctx.fillStyle = col('--dhr-absence-bg');
    for (const [v, c] of [[d.lost, hot], [d.ot, ot]]) { ctx.strokeStyle = c; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(x, Y(v), 4, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
