}
function coverTip(k) {
  const D = cv.D || coverSeries();
  cv.hover = Math.max(0, Math.min(D.length - 1, k));
  drawCover();
  const d = D[cv.hover];
  cv.tip.innerHTML = '<b>Week of ' + fmtDay(d.w * 7, { weekday: undefined, year: undefined }) + '</b>' + NF.format(d.lost) + ' h lost to absence<br>' + NF.format(d.ot) + ' h overtime · <span>' + (d.lost ? (d.ot / d.lost).toFixed(2) : '—') + ' h per hour lost</span>';
  placeTip(cv.tip, cv.plot, cv.X(cv.hover), cv.h * 0.3);
}
function hideCover() { cv.tip.hidden = true; cv.hover = -1; drawCover(); }
function startCover() { if (cv.intro || !cv.w || S.tab !== 'cover') return; cv.intro = true; tween(1000, (t) => { cv.prog = t; drawCover(); }); }
new ResizeObserver(() => {
  const dpr = Math.min(2, devicePixelRatio || 1);
  cv.w = cv.plot.clientWidth; cv.h = cv.plot.clientHeight;
  cv.c.width = Math.round(cv.w * dpr); cv.c.height = Math.round(cv.h * dpr);
  drawCover(); startCover();
}).observe(cv.plot);
cv.plot.addEventListener('pointermove', (e) => { if (!cv.D) return; const r = cv.plot.getBoundingClientRect(); coverTip(Math.round(((e.clientX - r.left - CP.l) / (cv.w - CP.l - CP.r)) * (cv.D.length - 1))); });
cv.plot.addEventListener('pointerleave', hideCover);
cv.plot.addEventListener('blur', hideCover);
cv.plot.addEventListener('focus', () => coverTip((cv.D || coverSeries()).length - 1));
cv.plot.addEventListener('keydown', (e) => {
  const st = { ArrowLeft: -1, ArrowRight: 1, Home: -999, End: 999 }[e.key];
  if (e.key === 'Escape') return hideCover();
  if (st === undefined) return;
  e.preventDefault(); coverTip((cv.hover < 0 ? 0 : cv.hover) + st);
});
function paintCover() {
  const D = coverSeries(), xs = D.map((d) => d.lost), ys = D.map((d) => d.ot), mx = xs.reduce((a, b) => a + b, 0) / xs.length, my = ys.reduce((a, b) => a + b, 0) / ys.length;
  let sxy = 0, sxx = 0, syy = 0;
