  drawCover(); startCover();
  const wa = 52 - S.wk, [a, b] = span();
  const rows = SITES.map((st, k) => {
    let abs = 0, sch = 0;
    for (let i = a; i <= b; i++) { abs += ABS[i].filter((s) => s.e.site === st.id).length; sch += SCHED[i][st.id]; }
    const o = OT[k].slice(wa).reduce((x, y) => x + y, 0);
