  });
  const tot = rows.reduce((t, r) => ({ abs: t.abs + r.abs, sch: t.sch + r.sch, o: t.o + r.o }), { abs: 0, sch: 0, o: 0 });
  const tr = (name, n, r, cls) => '<tr class="' + cls + '"><td>' + name + '</td><td>' + n + '</td><td>' + (r.abs / r.sch * 100).toFixed(1) + '%</td><td>' + NF.format(r.abs) + '</td><td>' + NF.format(r.o) + '</td><td>' + (r.o / (r.abs * 8)).toFixed(2) + '</td><td>' + gbp(r.o * RATE_OT) + '</td></tr>';
  $('[data-k="sitesrows"]').innerHTML = rows.map((r) => tr(esc(r.st.name), r.st.n, r, siteOk(r.st.id) && S.site !== 'all' ? '' : S.site === 'all' ? '' : 'is-dim')).join('') + tr('All sites', EMP.length, tot, 'is-total');
}

/* ================= Bradford ================= */
const brows = $('[data-k="brows"]');
function bradList() {
  const [k, dir] = S.bsort;
  return EMP.filter((e) => siteOk(e.site)).map((e) => Object.assign({ e }, bradford(e)))
    .filter((r) => S.trig === 'all' || r.t >= +S.trig)
    .sort((p, q) => (k === 'name' ? p.e.name.localeCompare(q.e.name) * dir : (p[k] - q[k]) * dir) || q.b - p.b || p.e.id - q.e.id);
