  const max = Math.max(401, ...list.map((r) => r.b));
  brows.innerHTML = list.slice(0, 80).map((r, i) => {
    const st = SITES.find((s) => s.id === r.e.site);
    return '<tr data-person="' + r.e.id + '" tabindex="' + (i ? -1 : 0) + '" aria-selected="' + (S.person === r.e.id) + '"><td><span class="dhr-absence-pn"><b>' + esc(r.e.name) + '</b><small>' + esc(st.name) + ' · ' + r.e.shift + '</small></span></td><td>' + r.s + '</td><td>' + r.d + '</td>' +
      '<td><span class="dhr-absence-bscore" style="--v:' + (r.b / max).toFixed(3) + '; --tc: ' + (r.t === 3 ? 'var(--dhr-absence-r-un)' : r.t === 2 ? 'var(--dhr-absence-r-lts)' : r.t === 1 ? 'var(--dhr-absence-hot)' : 'var(--dhr-absence-faint)') + '"><b>' + NF.format(r.b) + '</b><i aria-hidden="true"></i><span class="dhr-absence-trig" data-t="' + r.t + '">' + TRIG[r.t] + '</span></span></td>' +
      '<td><span class="dhr-absence-mini" aria-hidden="true">' + r.e.sp.filter((s) => s.end >= a && s.start <= b).map((s) => '<i style="--a:' + ((Math.max(a, s.start) - a) / len).toFixed(4) + '; --l:' + ((Math.min(b, s.end) - Math.max(a, s.start) + 1) / len).toFixed(4) + '; --c: var(--dhr-absence-r-' + s.r + ')"></i>').join('') + '</span></td></tr>';
  }).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--dhr-absence-muted);padding:24px">Nobody at this trigger level.</td></tr>';
  for (const th of $$('.dhr-absence-btable th[aria-sort]')) th.setAttribute('aria-sort', th.firstElementChild.dataset.bs === S.bsort[0] ? (S.bsort[1] > 0 ? 'ascending' : 'descending') : 'none');
}

/* ================= person drawer ================= */
const drawer = $('.dhr-absence-drawer');
let opener = null;
function openPerson(id, from) {
  const e = EMP[id];
  if (drawer.hidden) opener = from || null;
  S.person = id;
  const st = SITES.find((s) => s.id === e.site), B = bradford(e);
  $('[data-k="pmeta"]').textContent = st.name + ' · ' + e.shift + ' shift · ' + (e.pat === 'wk' ? 'Mon–Fri' : 'Wed–Sun');
  $('[data-k="pname"]').textContent = e.name;
  $('[data-k="pscore"]').innerHTML = '<div><span>Bradford</span><b>' + NF.format(B.b) + '</b><span>' + TRIG[B.t] + '</span></div><div><span>Spells</span><b>' + B.s + '</b><span>' + S.wk + ' weeks</span></div><div><span>Days</span><b>' + B.d + '</b><span>excl. long-term</span></div>';
  $('[data-k="pstrip"]').innerHTML = e.sp.map((s) => '<i style="--a:' + (s.start / ND).toFixed(4) + '; --l:' + ((s.end - s.start + 1) / ND).toFixed(4) + '; --c: var(--dhr-absence-r-' + s.r + ')" title="' + RBY[s.r].name + '"></i>').join('');
  $('[data-k="pspells"]').innerHTML = e.sp.length ? e.sp.slice().reverse().map((s) => '<li class="' + (s.r === 'lts' ? 'is-ex' : '') + '" style="--c: var(--dhr-absence-r-' + s.r + ')"><i aria-hidden="true"></i><span>' + RBY[s.r].name + (s.r === 'lts' ? ' · not counted' : '') + '</span><em>' + fmtDay(s.start, { weekday: undefined }) + (s.days > 1 ? ' · ' + s.days + ' days' : ' · 1 day') + '</em></li>').join('') : '<li>No absence in the last 52 weeks.</li>';
