  bk.textContent = booked ? 'Check-in booked · ' + booked : 'Book return-to-work check-in';
  bk.title = booked ? 'Already booked with their shift manager' : 'Book a 20-minute check-in with ' + e.name.split(' ')[0] + '’s shift manager';
  drawer.hidden = false;
  for (const tr of $$('tr[data-person]', brows)) tr.setAttribute('aria-selected', +tr.dataset.person === id);
  $('[data-k="pname"]').focus({ preventScroll: true });
