  const done = () => { drawer.hidden = true; };
  if (RM) done(); else drawer.animate([{ opacity: 1, translate: '0 0' }, { opacity: 0, translate: '22px 0' }], { duration: 160, easing: 'ease-in' }).finished.then(done);
