/* ================= render + events ================= */
function render() {
  paintKpis(); paintReasons();
  if (S.tab === 'cal') { paintHeat(); paintDow(); paintMonths(); paintDay(); }
  else if (S.tab === 'cover') paintCover();
  else paintBrad();
}
function setTab(t) {
  if (S.tab === t) return;
  S.tab = t;
  for (const b of $$('[role=tab]')) { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; }
