    return toast('Check-in booked for ' + e.name + ' · ' + when);
  }
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !drawer.hidden) { e.preventDefault(); closePerson(); return; }
  const tab = e.target.closest('[role=tab]');
  if (tab && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
    e.preventDefault();
    const items = $$('[role=tab]'), n = items[(items.indexOf(tab) + (e.key === 'ArrowRight' ? 1 : -1) + items.length) % items.length];
