/* ---------- shell shared by every view: scoped resets, the root box ---------- */
.dhr-learn {
  width: 100%;
  height: var(--dhr-learn-h, 680px);
  container-type: inline-size;
  container-name: dhr-learn;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhr-learn-bg);
  color: var(--dhr-learn-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--dhr-learn-accent);
  scrollbar-color: var(--dhr-learn-line2) transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; text-transform: inherit; letter-spacing: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: inherit; -webkit-tap-highlight-color: transparent; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dhr-learn-focus, var(--dhr-learn-accent)); outline-offset: 2px; }
  & :is(h1, h2, h3, h4, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :is(ul, ol) { list-style: none; }
  & :is(h1, h2, h3, h4) { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & [hidden] { display: none !important; }
  & table { border-collapse: collapse; border-spacing: 0; }
  & :is(th, td) { padding: 0; font-weight: inherit; text-align: left; }
  & select, & input { font: inherit; color: inherit; }
}

@property --dhr-learn-n { syntax: "<integer>"; inherits: false; initial-value: 0; }
@property --dhr-learn-arc { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@keyframes dhr-learn-in { from { opacity: 0; translate: 0 6px; } }
@keyframes dhr-learn-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhr-learn-fade { from { opacity: 0; } }
@keyframes dhr-learn-spin { to { rotate: 1turn; } }
@keyframes dhr-learn-row { from { opacity: 0.2; translate: 0 8px; } }

.dhr-learn {
  /* re-theme: ground, ink, progress accent, warning and risk */
  --dhr-learn-bg: oklch(0.205 0.024 168);
  --dhr-learn-ink: oklch(0.95 0.016 150);
  --dhr-learn-accent: oklch(0.88 0.17 126);
  --dhr-learn-warn: oklch(0.82 0.13 78);
  --dhr-learn-risk: oklch(0.71 0.15 18);

  --dhr-learn-card: color-mix(in oklch, var(--dhr-learn-bg), var(--dhr-learn-ink) 5%);
  --dhr-learn-raise: color-mix(in oklch, var(--dhr-learn-bg), var(--dhr-learn-ink) 10%);
  --dhr-learn-sunk: color-mix(in oklch, var(--dhr-learn-bg), black 25%);
  --dhr-learn-line: color-mix(in oklch, var(--dhr-learn-ink) 9%, transparent);
  --dhr-learn-line2: color-mix(in oklch, var(--dhr-learn-ink) 17%, transparent);
  --dhr-learn-muted: color-mix(in oklch, var(--dhr-learn-ink) 60%, var(--dhr-learn-bg));
  --dhr-learn-faint: color-mix(in oklch, var(--dhr-learn-ink) 36%, var(--dhr-learn-bg));
  --dhr-learn-accent-dim: color-mix(in oklch, var(--dhr-learn-accent) 30%, var(--dhr-learn-bg));
  --dhr-learn-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dhr-learn-spring: linear(0, 0.01, 0.04 2.2%, 0.16 4.8%, 0.74 13.4%, 0.95 17.4%, 1.03 20.4%, 1.065 23.8%, 1.07 27%, 1.045 32%, 1.008 42%, 0.996 50%, 1);
  --dhr-learn-mono: ui-monospace, Menlo, Consolas, monospace;
  color-scheme: dark;
}

.dhr-learn {
  .dhr-learn-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhr-learn-muted); }
  .dhr-learn-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .dhr-learn-app { display: grid; height: 100%; grid-template-columns: 218px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  /* ---------- side ---------- */
  .dhr-learn-side { grid-area: side; min-height: 0; overflow: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; background: var(--dhr-learn-sunk); border-right: 1px solid var(--dhr-learn-line); }
  .dhr-learn-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dhr-learn-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 10px; background: var(--dhr-learn-accent); fill: none; stroke: var(--dhr-learn-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dhr-learn-brand span { display: grid; line-height: 1.25; min-width: 0; }
  .dhr-learn-brand b { font-size: 14px; font-weight: 700; }
  .dhr-learn-brand small { font-size: 11px; color: var(--dhr-learn-muted); }
  .dhr-learn-nav { display: grid; gap: 2px; }
  .dhr-learn-nav button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; font-weight: 580; color: var(--dhr-learn-muted); transition: background-color 150ms, color 150ms; }
  .dhr-learn-nav button:hover { color: var(--dhr-learn-ink); background: color-mix(in oklch, var(--dhr-learn-ink) 6%, transparent); }
  .dhr-learn-nav button[aria-current="page"] { color: var(--dhr-learn-bg); background: var(--dhr-learn-accent); }
  .dhr-learn-nav svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhr-learn-courses { display: grid; gap: 7px; }
  .dhr-learn-courses .dhr-learn-eyebrow { padding: 0 6px; }
  .dhr-learn-courses ul { display: grid; gap: 2px; }
  .dhr-learn-courses button { width: 100%; display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; grid-template-rows: auto 3px; align-items: center; gap: 4px 8px; padding: 6px 8px; border-radius: 8px; font-size: 12px; text-align: left; transition: background-color 150ms, color 150ms; }
  .dhr-learn-courses button:hover { background: color-mix(in oklch, var(--dhr-learn-ink) 6%, transparent); }
  .dhr-learn-courses button::before { content: ""; width: 12px; height: 12px; border-radius: 4px; box-shadow: inset 0 0 0 1.5px var(--dhr-learn-line2); transition: background-color 160ms, box-shadow 160ms; }
  .dhr-learn-courses button[aria-pressed="true"]::before { background: var(--dhr-learn-accent); box-shadow: none; }
  .dhr-learn-courses button[aria-pressed="false"] { color: var(--dhr-learn-faint); }
  .dhr-learn-courses button[aria-disabled="true"] { cursor: default; }
  .dhr-learn-courses span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-learn-courses em { font: 500 10.5px var(--dhr-learn-mono); font-style: normal; color: var(--dhr-learn-muted); }
  .dhr-learn-courses i { grid-column: 2 / -1; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--dhr-learn-accent-dim) calc(var(--v) * 100%), var(--dhr-learn-line) 0); }
  .dhr-learn-due { margin-top: auto; display: grid; gap: 1px; padding: 12px 8px 0; border-top: 1px solid var(--dhr-learn-line); }
  .dhr-learn-due b { font-size: 22px; font-weight: 720; letter-spacing: -0.03em; color: var(--dhr-learn-accent); font-variant-numeric: tabular-nums; }
  .dhr-learn-due span { font-size: 11.5px; color: var(--dhr-learn-muted); }

  /* ---------- header ---------- */
  .dhr-learn-head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 18px 22px 12px; }
  .dhr-learn-title { display: grid; gap: 4px; min-width: 0; }
  .dhr-learn-title h2 { font-size: clamp(19px, 2.3cqi, 28px); font-weight: 720; letter-spacing: -0.03em; line-height: 1.1; }
  .dhr-learn-hero { display: flex; align-items: center; gap: 10px; }
  .dhr-learn-pct { font-size: clamp(30px, 4cqi, 46px); font-weight: 760; letter-spacing: -0.05em; line-height: 1; color: var(--dhr-learn-accent); font-variant-numeric: tabular-nums; counter-reset: dhr-learnp var(--dhr-learn-n); transition: --dhr-learn-n 1200ms cubic-bezier(0.16, 1, 0.3, 1); }
  .dhr-learn-pct::after { content: counter(dhr-learnp) "%"; }
  .dhr-learn-herol { display: grid; font-size: 12px; font-weight: 600; color: var(--dhr-learn-muted); line-height: 1.3; }
  .dhr-learn-herol em { font-style: normal; font-weight: 650; }
  .dhr-learn-herol em[data-tone="ok"] { color: var(--dhr-learn-accent); }
  .dhr-learn-herol em[data-tone="warn"] { color: var(--dhr-learn-warn); }
  .dhr-learn-herol em[data-tone="risk"] { color: var(--dhr-learn-risk); }

  .dhr-learn-main { grid-area: main; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 0 22px 18px; }
  .dhr-learn-view { animation: dhr-learn-in 360ms var(--dhr-learn-ease) both; }
  .dhr-learn-card { display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: 0; padding: 12px 14px; border-radius: 14px; background: var(--dhr-learn-card); box-shadow: inset 0 0 0 1px var(--dhr-learn-line); }
  .dhr-learn-cardhead { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 6px; }
  .dhr-learn-cardhead h3 { font-size: 13px; font-weight: 680; }
  .dhr-learn-note { font-size: 11.5px; color: var(--dhr-learn-muted); }
  .dhr-learn-key { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dhr-learn-muted); }
  .dhr-learn-key li { display: inline-flex; align-items: center; gap: 6px; }
  .dhr-learn-key i { width: 16px; height: 0; border-top: 2.5px solid var(--dhr-learn-accent); }
  .dhr-learn-key .is-proj { border-top-style: dashed; }
  .dhr-learn-key .is-need { border-top: 1.5px dotted var(--dhr-learn-ink); opacity: 0.7; }

  /* ---------- burn-up ---------- */
  .dhr-learn-burn { display: grid; gap: 12px; height: 100%; min-height: 470px; grid-template-rows: minmax(0, 1fr) auto; }
  .dhr-learn-plot { position: relative; flex: 1; min-height: 190px; cursor: crosshair; border-radius: 8px; }
  .dhr-learn-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; font: 500 10.5px system-ui, sans-serif; }
  .dhr-learn-svg text { fill: var(--dhr-learn-muted); font-variant-numeric: tabular-nums; }
  .dhr-learn-grid line { stroke: var(--dhr-learn-line); }
  .dhr-learn-grid .is-base { stroke: var(--dhr-learn-line2); }
  .dhr-learn-area { opacity: 0.9; }
  .is-drawn .dhr-learn-fan, .is-drawn .dhr-learn-proj { animation: none; }
  .dhr-learn-act { fill: none; stroke: var(--dhr-learn-accent); stroke-width: 2.4; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; animation: dhr-learn-draw 1300ms var(--dhr-learn-ease) 100ms both; }
  .dhr-learn-fan { fill: var(--dhr-learn-accent); opacity: 0.12; animation: dhr-learn-fade 600ms var(--dhr-learn-ease) 1200ms both; }
  .dhr-learn-proj { fill: none; stroke: var(--dhr-learn-accent); stroke-width: 2; stroke-dasharray: 5 5; opacity: 0.85; animation: dhr-learn-fade 600ms var(--dhr-learn-ease) 1200ms both; }
  .dhr-learn-need { fill: none; stroke: var(--dhr-learn-ink); stroke-width: 1.3; stroke-dasharray: 1.5 3.5; opacity: 0.55; }
  .dhr-learn-goal { stroke: var(--dhr-learn-ink); stroke-width: 1; opacity: 0.4; }
  .dhr-learn-mark line { stroke: var(--dhr-learn-warn); stroke-width: 1; stroke-dasharray: 2 3; opacity: 0.7; }
  .dhr-learn-mark text { fill: var(--dhr-learn-warn) !important; font-size: 10px; font-weight: 650; }
  .dhr-learn-today line { stroke: var(--dhr-learn-ink); stroke-width: 1; opacity: 0.55; }
  .dhr-learn-today text { fill: var(--dhr-learn-ink) !important; font-weight: 700; font-size: 10px; letter-spacing: 0.06em; text-transform: uppercase; }
  .dhr-learn-endlab { font-weight: 700; font-size: 11px !important; }
  .dhr-learn-endlab[data-tone="ok"] { fill: var(--dhr-learn-accent) !important; } .dhr-learn-endlab[data-tone="warn"] { fill: var(--dhr-learn-warn) !important; } .dhr-learn-endlab[data-tone="risk"] { fill: var(--dhr-learn-risk) !important; }
  .dhr-learn-cross line { stroke: var(--dhr-learn-ink); stroke-opacity: 0.4; stroke-dasharray: 3 3; }
  .dhr-learn-cross circle { fill: var(--dhr-learn-bg); stroke: var(--dhr-learn-accent); stroke-width: 2; }
  .dhr-learn-tip {
    position: absolute; left: 0; top: 0; z-index: 8; min-width: 170px; padding: 8px 11px; border-radius: 10px; pointer-events: none; font-size: 11.5px; line-height: 1.45;
    background: var(--dhr-learn-raise); color: var(--dhr-learn-ink); box-shadow: 0 0 0 1px var(--dhr-learn-line2), 0 16px 30px -12px oklch(0 0 0 / 0.75); transition: translate 90ms var(--dhr-learn-ease);
  }
  .dhr-learn-tip b { display: block; font-size: 12px; margin-bottom: 2px; }
  .dhr-learn-tip span { color: var(--dhr-learn-muted); }

  .dhr-learn-depts { display: grid; grid-template-columns: repeat(auto-fit, minmax(104px, 1fr)); gap: 8px; }
  .dhr-learn-dept {
    display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-rows: auto auto auto; align-items: center; column-gap: 8px; row-gap: 2px;
    padding: 10px; border-radius: 12px; background: var(--dhr-learn-card); box-shadow: inset 0 0 0 1px var(--dhr-learn-line); text-align: left;
    container: dhr-learn-dcard / inline-size;
    transition: background-color 160ms, box-shadow 160ms, translate 300ms var(--dhr-learn-spring);
    animation: dhr-learn-in 420ms var(--dhr-learn-ease) calc(var(--i) * 45ms) both;
  }
  .dhr-learn-dept:hover { background: var(--dhr-learn-raise); translate: 0 -2px; }
  .dhr-learn-dept[aria-pressed="true"] { box-shadow: inset 0 0 0 1.5px var(--dhr-learn-accent); background: color-mix(in oklch, var(--dhr-learn-accent) 9%, var(--dhr-learn-card)); }
  .dhr-learn-ring {
    grid-row: 1; grid-column: 1; position: relative; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; margin-bottom: 4px;
    background: conic-gradient(var(--rc, var(--dhr-learn-accent)) var(--dhr-learn-arc), var(--dhr-learn-line2) 0);
    transition: --dhr-learn-arc 1100ms var(--dhr-learn-ease);
  }
  .dhr-learn-ring::before { content: ""; position: absolute; inset: 5px; border-radius: 50%; background: var(--dhr-learn-card); }
  .dhr-learn-dept:hover .dhr-learn-ring::before { background: var(--dhr-learn-raise); }
  .dhr-learn-ring b { position: relative; font: 700 11px var(--dhr-learn-mono); font-variant-numeric: tabular-nums; }
  .dhr-learn-depts.is-in .dhr-learn-ring { --dhr-learn-arc: var(--p); }
  .dhr-learn-dept > span { grid-column: 1 / -1; font-size: 12px; font-weight: 650; line-height: 1.25; text-wrap: balance; }
  .dhr-learn-dept small { grid-column: 1 / -1; font-size: 10.5px; color: var(--dhr-learn-muted); line-height: 1.3; }
  .dhr-learn-dept em { grid-row: 1; grid-column: 2; align-self: start; justify-self: end; white-space: nowrap; font-style: normal; font-size: 10px; font-weight: 700; padding: 0 6px; border-radius: 99px; }
  /* too narrow for ring and badge side by side: the badge drops under the head-count */
  /* card-sized container queries: a smaller ring first, then the badge drops under the head-count */
  @container dhr-learn-dcard (width < 104px) {
    .dhr-learn-ring { width: 34px; height: 34px; }
    .dhr-learn-ring::before { inset: 4px; }
    .dhr-learn-ring b { font-size: 10px; }
  }
  @container dhr-learn-dcard (width < 93px) {
    .dhr-learn-dept em { grid-row: 4; grid-column: 1 / -1; justify-self: start; margin-top: 4px; }
  }
  .dhr-learn-dept em[data-tone="ok"] { background: color-mix(in oklch, var(--dhr-learn-accent) 18%, transparent); color: var(--dhr-learn-accent); }
  .dhr-learn-dept em[data-tone="warn"] { background: color-mix(in oklch, var(--dhr-learn-warn) 18%, transparent); color: var(--dhr-learn-warn); }
  .dhr-learn-dept em[data-tone="risk"] { background: color-mix(in oklch, var(--dhr-learn-risk) 20%, transparent); color: var(--dhr-learn-risk); }

  /* ---------- learners ---------- */
  .dhr-learn-people { display: grid; gap: 10px; height: 100%; min-height: 420px; grid-template-rows: auto minmax(0, 1fr); }
  .dhr-learn-pbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .dhr-learn-seg { display: flex; padding: 2px; border-radius: 9px; background: var(--dhr-learn-sunk); box-shadow: inset 0 0 0 1px var(--dhr-learn-line); }
  .dhr-learn-seg button { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dhr-learn-muted); white-space: nowrap; transition: background-color 160ms, color 160ms; }
  .dhr-learn-seg button:hover { color: var(--dhr-learn-ink); }
  .dhr-learn-seg [aria-checked="true"] { background: var(--dhr-learn-raise); color: var(--dhr-learn-ink); box-shadow: 0 0 0 1px var(--dhr-learn-line2); }
  .dhr-learn-chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 8px 5px 11px; border-radius: 99px; font-size: 11.5px; font-weight: 640; background: color-mix(in oklch, var(--dhr-learn-accent) 16%, transparent); color: var(--dhr-learn-accent); }
  .dhr-learn-chip svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  .dhr-learn-send { margin-left: auto; display: inline-flex; align-items: center; gap: 7px; padding: 7px 13px; border-radius: 9px; font-size: 12.5px; font-weight: 680; background: var(--dhr-learn-accent); color: var(--dhr-learn-bg); transition: background-color 150ms, scale 200ms var(--dhr-learn-spring), opacity 150ms; }
  .dhr-learn-send svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
  .dhr-learn-send:hover:not([aria-disabled="true"]) { background: color-mix(in oklch, var(--dhr-learn-accent), white 18%); }
  .dhr-learn-send:active:not([aria-disabled="true"]) { scale: 0.97; }
  .dhr-learn-send[aria-disabled="true"] { background: var(--dhr-learn-line2); color: var(--dhr-learn-muted); }
  .dhr-learn-send.is-busy svg { animation: dhr-learn-spin 700ms linear infinite; }
  .dhr-learn-tablewrap { min-height: 0; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dhr-learn-card); box-shadow: inset 0 0 0 1px var(--dhr-learn-line); }
  .dhr-learn-table { width: 100%; font-size: 12px; font-variant-numeric: tabular-nums; }
  .dhr-learn-table th { position: sticky; top: 0; z-index: 1; padding: 9px 10px 7px; background: var(--dhr-learn-card); border-bottom: 1px solid var(--dhr-learn-line2); font-size: 10.5px; font-weight: 650; letter-spacing: 0.07em; text-transform: uppercase; color: var(--dhr-learn-muted); white-space: nowrap; }
  .dhr-learn-table th button { display: inline-flex; gap: 3px; border-radius: 4px; }
  .dhr-learn-table th button:hover { color: var(--dhr-learn-ink); }
  [aria-sort="ascending"] > button::after { content: "\2191"; color: var(--dhr-learn-ink); }
  [aria-sort="descending"] > button::after { content: "\2193"; color: var(--dhr-learn-ink); }
  .dhr-learn-table td { padding: 7px 10px; border-bottom: 1px solid var(--dhr-learn-line); white-space: nowrap; }
  .dhr-learn-cbcol { width: 34px; }
  .dhr-learn-table input[type="checkbox"] { width: 15px; height: 15px; margin: 0; accent-color: var(--dhr-learn-accent); cursor: pointer; }
  .dhr-learn-table tbody tr { transition: background-color 130ms; }
  .dhr-learn-table tbody tr:hover { background: color-mix(in oklch, var(--dhr-learn-ink) 4%, transparent); }
  .dhr-learn-table tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dhr-learn-accent) 9%, transparent); }
  @supports (animation-timeline: view()) {
    .dhr-learn-table tbody tr { animation: dhr-learn-row linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
  }
  .dhr-learn-ln { display: grid; line-height: 1.25; }
  .dhr-learn-ln b { font-weight: 620; }
  .dhr-learn-ln small { font-size: 11px; color: var(--dhr-learn-muted); }
  .dhr-learn-ln small mark { background: none; color: var(--dhr-learn-warn); font-weight: 650; }
  .dhr-learn-dots { display: inline-flex; gap: 4px; vertical-align: middle; margin-right: 8px; }
  .dhr-learn-dots i { width: 10px; height: 10px; border-radius: 3px; box-shadow: inset 0 0 0 1.5px var(--dhr-learn-line2); }
  .dhr-learn-dots i.is-done { background: var(--dhr-learn-accent); box-shadow: none; }
  .dhr-learn-dots i.is-off { opacity: 0.25; }
  .dhr-learn-empty { padding: 26px; text-align: center; color: var(--dhr-learn-muted); }

  /* ---------- matrix ---------- */
  .dhr-learn-mx { display: grid; grid-template-columns: minmax(118px, 1.3fr) repeat(5, minmax(56px, 1fr)) minmax(56px, 0.9fr); gap: 3px; overflow-x: auto; }
  .dhr-learn-mx [role="row"] { display: contents; }
  .dhr-learn-mx .dhr-learn-mh { padding: 4px 6px 6px; font-size: 10.5px; font-weight: 650; line-height: 1.25; color: var(--dhr-learn-muted); align-self: end; text-wrap: balance; }
  .dhr-learn-mx .dhr-learn-mr { padding: 0 8px; font-size: 12px; font-weight: 620; align-self: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhr-learn-cell {
    height: 44px; border-radius: 6px; display: grid; place-items: center; font: 650 12px var(--dhr-learn-mono); font-variant-numeric: tabular-nums;
    background: color-mix(in oklch, var(--dhr-learn-accent) clamp(4%, (var(--v) - 0.3) * 140%, 90%), var(--dhr-learn-sunk)); color: var(--dhr-learn-ink);
    transition: scale 220ms var(--dhr-learn-spring), box-shadow 150ms; animation: dhr-learn-fade 400ms var(--dhr-learn-ease) calc(var(--i) * 18ms) both;
  }
  .dhr-learn-cell.is-hi { color: var(--dhr-learn-bg); font-weight: 750; }
  .dhr-learn-cell:hover { scale: 1.06; box-shadow: 0 0 0 2px var(--dhr-learn-ink); position: relative; z-index: 1; }
  .dhr-learn-cell.is-total { cursor: default; background: transparent; color: var(--dhr-learn-ink); box-shadow: inset 0 0 0 1px var(--dhr-learn-line2); }
  .dhr-learn-cell.is-total:hover { scale: 1; box-shadow: inset 0 0 0 1px var(--dhr-learn-line2); }

  .dhr-learn-toast {
    position: absolute; z-index: 30; left: 50%; bottom: 16px; translate: -50% 0; padding: 8px 14px; border-radius: 10px; max-width: calc(100% - 32px);
    background: var(--dhr-learn-ink); color: var(--dhr-learn-bg); font-size: 12px; font-weight: 600; opacity: 0; scale: 0.95; pointer-events: none;
    transition: opacity 200ms, scale 360ms var(--dhr-learn-spring), translate 360ms var(--dhr-learn-spring);
  }
  .dhr-learn-toast.is-on { opacity: 1; scale: 1; translate: -50% -4px; }
}

@container dhr-learn (width < 960px) {
  .dhr-learn {
    .dhr-learn-app { grid-template-columns: 190px minmax(0, 1fr); }
    .dhr-learn-head { flex-direction: column; align-items: flex-start; gap: 8px; }
  }
}
@container dhr-learn (width < 760px) {
  .dhr-learn {
    .dhr-learn-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "side" "head" "main"; }
    .dhr-learn-side { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 8px 10px; padding: 10px 14px; overflow: visible; border-right: 0; border-bottom: 1px solid var(--dhr-learn-line); }
    .dhr-learn-brand span { display: none; }
    .dhr-learn-brand { padding: 0; }
    .dhr-learn-nav { display: flex; flex: 1; overflow-x: auto; scrollbar-width: none; }
    .dhr-learn-nav button { padding: 7px 10px; white-space: nowrap; }
    .dhr-learn-courses { flex: 1 1 100%; }
    .dhr-learn-courses .dhr-learn-eyebrow { display: none; }
