/* ================= matrix ================= */
function paintMatrix() {
  const head = '<div role="row"><span class="dhr-learn-mh"></span>' + COURSES.map((c) => '<span class="dhr-learn-mh" role="columnheader">' + esc(c.short) + '</span>').join('') + '<span class="dhr-learn-mh" role="columnheader">All five</span></div>';
  let i = 0;
  const rows = DEPTS.map((d) => {
    const L = LEARNERS.filter((l) => l.dept === d.id);
    const cells = COURSES.map((c, k) => {
      const done = L.filter((l) => l.t[k] <= TODAY).length, v = done / L.length;
      return '<button type="button" role="gridcell" class="dhr-learn-cell' + (v >= 0.72 ? ' is-hi' : '') + '" data-cell="' + d.id + ':' + c.id + '" style="--v:' + v.toFixed(3) + '; --i:' + (i++) + '" title="' + esc(d.name) + ' · ' + esc(c.short) + ': ' + done + ' of ' + L.length + ' done. Open the ' + (L.length - done) + ' still to do.">' + Math.round(v * 100) + '%</button>';
    }).join('');
    const tot = L.reduce((s, l) => s + l.t.filter((t) => t <= TODAY).length, 0) / (L.length * 5);
    return '<div role="row"><span class="dhr-learn-mr" role="rowheader">' + esc(d.name) + '</span>' + cells + '<span class="dhr-learn-cell is-total" role="gridcell" style="--v:0; --i:' + (i++) + '">' + Math.round(tot * 100) + '%</span></div>';
  }).join('');
  $('[data-k="mx"]').innerHTML = head + rows;
}

/* ================= render + events ================= */
const H2 = { burn: 'Will we make the deadline?', people: 'Who still has training to do', matrix: 'Where the gaps are' };
