  if (t.matches('input[data-pick]')) { const id = +t.dataset.pick; if (t.checked) S.sel.add(id); else S.sel.delete(id); const all = $('input[data-act="all"]'), ids = $$('input[data-pick]', rowsEl).map((x) => +x.dataset.pick), n = ids.filter((x) => S.sel.has(x)).length; all.checked = n === ids.length; all.indeterminate = n > 0 && n < ids.length; return paintSend(); }
  if (t.matches('input[data-act="all"]')) { const ids = $$('input[data-pick]', rowsEl).map((x) => +x.dataset.pick); ids.forEach((id) => (t.checked ? S.sel.add(id) : S.sel.delete(id))); $$('input[data-pick]', rowsEl).forEach((x) => { x.checked = t.checked; }); return paintSend(); }
  if (t.tagName === 'INPUT') return;
