  if (t.dataset.course) { const k = t.dataset.course; if (S.courses.has(k)) S.courses.delete(k); else S.courses.add(k); render(); const b = $('[data-course="' + k + '"]'); if (b) b.focus({ preventScroll: true }); return; }
  if (t.dataset.dept) { S.dept = S.dept === t.dataset.dept ? null : t.dataset.dept; S.todo = null; render(); const b = $('[data-dept="' + t.dataset.dept + '"]'); if (b) b.focus({ preventScroll: true }); return; }
  if (t.dataset.st) { S.st = t.dataset.st; for (const b of $$('[data-st]')) { b.setAttribute('aria-checked', b === t); b.tabIndex = b === t ? 0 : -1; } return paintPeople(); }
  if (t.dataset.ps) { const k = t.dataset.ps; S.sort = [k, S.sort[0] === k ? -S.sort[1] : 1]; return paintPeople(); }
  if (t.dataset.act === 'clear-dept') { S.dept = null; S.todo = null; render(); return $('[data-st="all"]').focus(); }
  if (t.dataset.cell) {
