root.addEventListener('keydown', (e) => {
  if (e.target.closest('.dhr-learn-nav') && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
    e.preventDefault();
    const items = $$('.dhr-learn-nav button'), i = items.indexOf(e.target.closest('button'));
    items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); return;
  }
  if (e.target.getAttribute('role') === 'radio') {
    const st = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key];
    if (!st) return;
    e.preventDefault();
    const items = $$('[role=radio]', e.target.parentElement), n = items[(items.indexOf(e.target) + st + items.length) % items.length];
    n.focus(); n.click(); return;
  }
  const cell = e.target.closest('.dhr-learn-cell');
  if (cell && !cell.classList.contains('is-total')) {
    const cells = $$('button.dhr-learn-cell'), i = cells.indexOf(cell), st = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 5, ArrowUp: -5 }[e.key];
